INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(12489, 'koKR', 'Witaj w Kotlinie Sholazar', 'Skąd się tu $gwziąłeś:wzięłaś;? Chyba nie przysłał cię też ten dureń arcymag?$B$BMasz szczęście, że jesteś w jednym kawałku, $gchłopcze:dziewczyno;! Prawie cię wysadzili!$B$BTa dżungla to cholernie niebezpieczne miejsce, zwłaszcza kiedy kręci się tu spółka Gitgeszeft.$B$BRuszaj się! Idź do szefa... on się tobą zajmie. Obóz jest na końcu tamtej ścieżki, na północnym zachodzie.$B$BNo, zmykaj!', 'Idź ścieżką na północny zachód, do obozu, o którym wspomniał Monte.', '', '', '', '', '', '', 0),
(12520, 'koKR', 'Łowy na nosorożce: próba', 'Żadne twarde lądowanie nie powstrzyma starego Hemeta przed upolowaniem największej zwierzyny, jaką ma do zaoferowania Sholazar. W dziczy na północny zachód od obozu dżunglą rządzą potężne odłamkorogie nosorożce. Możesz dowieść swojej wartości dla ekspedycji, $gchłopcze:dziewczyno;, pokazując mi, że jesteś $gdość twardy:dość twarda;, by stawić czoła tym potężnym bestiom.', 'Zabij 15 odłamkorogich nosorożców i wróć do Hemeta Nesingwary\'ego w Obozie Nesingwary\'ego.', '', 'Wróć do Hemeta Nesingwary\'ego w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12521, 'koKR', 'Gdzie w świecie jest Hemet Nesingwary?', 'Kiedy usłyszałem, że legendarny Hemet Nesingwary wyrusza do Kotliny Sholazar, zaproponowałem, że pomogę sfinansować jego ekspedycję. Niewiele wiemy o Sholazar, ale podobno to bujny raj pośrodku tego skutego lodem kontynentu.$B$BHemet zgodził się przysyłać nam próbki egzotycznych roślin, składników i kryształów. Nie mamy od niego żadnych wieści. Monte Lufostrzał miał im dowieźć zapasy, ale on też nie wrócił. Jeśli się tym zajmiesz, poślę cię tam moją fruwającą maszyną.', 'Porozmawiaj z arcymagiem Pentarusem, gdy będziesz $ggotów:gotowa; do drogi do Kotliny Sholazar. Na miejscu porozmawiaj z Monte Lufostrzałem w Dzikim Namorzynie w Kotlinie Sholazar.', '', '', '', '', '', '', 0),
(12522, 'koKR', 'Potrzebujesz silnika? Weź silnik', 'Zniszczona... kompletnie zniszczona! Mówiłem tej pani kapitan, żeby uważała na tak cenny ładunek, ale czy mnie posłuchała? Nie!$B$BKiedy statek osiadł na mieliźnie, uszkodził moją fruwającą maszynę, Ducha Gnomoregan. Teraz nie mamy jak wysyłać raportów!$B$BIstnieje jednak szansa, że wybryki spółki Gitgeszeft obrócą się na naszą korzyść. Zestrzelili inną fruwającą maszynę mniej więcej tam, gdzie Monte spadł na spadochronie w bagno na wschodzie. Idź tam i odzyskaj silnik. To może być nasza jedyna nadzieja.', 'Weslex Szybkoklucz w Obozie Nesingwary\'ego chce, żebyś $gprzyniósł:przyniosła; mu silnik fruwającej maszyny.', '', 'Wróć do Weslexa Szybkoklucza w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12523, 'koKR', 'Masz część? Daj część', 'Świetnie, skoro mamy już silnik, będziemy potrzebować całej gamy innych części, żeby znów mogła latać. Spokojnie, wiem, co robię.$B$BDobry mechanik potrafi skleić swoje dzieła byle czym, ale lepiej, żeby do tego nie doszło.$B$BW każdym razie te tępaki ze spółki Gitgeszeft mają mnóstwo części zamiennych do sprzętu górniczego porozrzucanych po całym Wykopalisku Swindlegrina, po drugiej stronie tamtego żółtego kryształowego filaru na północnym wschodzie. Zgarnij kilka i przynieś je tutaj.', 'Przynieś 7 części zamiennych spółki Gitgeszeft Weslexowi Szybkokluczowi w Obozie Nesingwary\'ego.', '', 'Wróć do Weslexa Szybkoklucza w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12524, 'koKR', 'Nieudany interes spółki Gitgeszeft', 'Od kiedy tu przybyliśmy, spółka Gitgeszeft utrudnia nam zabezpieczenie obozowiska i zbadanie okolicy. Normalnie nie obchodziłoby nas, co knują, ale zaczęli nękać naszych zwiadowców i zestrzeliwać loty z zaopatrzeniem.$B$BNie możemy puścić płazem takiej zniewagi. Ekspedycja Hemeta Nesingwary\'ego przybyła tu polować i polować będzie.$B$BUdaj się na Wykopalisko Swindlegrina, po drugiej stronie kryształowego filaru na północnym wschodzie, i zabij każdego pracownika spółki Gitgeszeft, jakiego zobaczysz!', 'Debaar w Obozie Nesingwary\'ego chce, żebyś $gzabił:zabiła; 15 członków spółki Gitgeszeft. Możesz zabijać zbirów albo wydobywców spółki Gitgeszeft.', '', 'Wróć do Debaar w Obozie Nesingwary\'ego w Kotlinie Sholazar.', 'Zabici członkowie spółki Gitgeszeft', '', '', '', 0),
(12525, 'koKR', 'Zetrzyj mu ten uśmieszek z twarzy', 'Jeśli mamy na dobre zamknąć kopalnię brygadzisty Cwaniuśmiecha, musimy go stąd przegnać, ale uważaj. Jego ochroniarz, Pasztecik, to wielki, wredny ogr i raczej nie pozwoli ci zobaczyć się z brygadzistą bez walki.$B$BObaj pewnie zajmują platformę, z której widać całą operację spółki Gitgeszeft na Wykopalisku Swindlegrina.$B$BPamiętaj, wykopalisko leży po drugiej stronie Filaru Muśniętego Słońcem, na północnym wschodzie. Powodzenia, $N.', 'Zabij brygadzistę Cwaniuśmiecha i Pasztecika, a potem wróć do Debaar w Obozie Nesingwary\'ego.', '', 'Wróć do Debaar w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12526, 'koKR', 'Łowy na nosorożce: pościg', 'No to postanowione. Odszukamy tego miejscowego mędrca i zamienimy z nim słowo. Raczej jednak nie zaoferuje nam swoich usług z własnej woli.$B$BPodobno ma mały szałas przy Kościach Nozronna, tuż za rzeką na południu. Odszukaj go, przedstaw się i zapytaj, czego potrzebuje, żeby pomóc nam wytropić tego nosorożcowego patriarchę.', 'Porozmawiaj z wyrocznią Soo-rahmem przy Kościach Nozronna.', '', '', '', '', '', '', 0),
(12528, 'koKR', 'Gra pozorów', 'Moja zdobycz! Ty zabrać moja zdobycz!$B$B<Gekgek drwi z ciebie, wymachując włócznią.>$B$BTy $ggłupi:głupia;, $r. Teraz ty dłużny Gekgek! Ty być $gniewolnik:niewolnica; Szalonego Serca. Ty zabić dużo więcej bestii dla Szalonego Serca.$B$BTy iść na Wzgórze Szalonego Serca na północnym wschodzie – ty powiedzieć wielki szaman Rakjak, że ty $gnowy niewolnik:nowa niewolnica;.$B$BIdź, $r! Idź, albo ja zadrwić z ciebie drugi raz!$B$B<Gekgek groźnie wymachuje włócznią.>', 'Zgłoś się do wielkiego szamana Rakjaka na Wzgórzu Szalonego Serca jako $gnowy „niewolnik”:nowa „niewolnica”;.', '', '', '', '', '', '', 0),
(12529, 'koKR', 'Niewolnik łowcy małp', 'Ty myśleć, że ty taki wielki łowca, co? Ty nie Szalone Serce, ty nie znać łowów.$B$BGoregek wielki łowca małp. On zabić tyle małp, że ty nie policzyć na pazurach.$B$BTy iść z Goregekiem i polować na twardopięściów na wschodzie. Ty $gniewolnik:niewolnica;, $r. Ty robić, co Goregek każe.', 'Zabij 8 zbieraczy z Twardopięściów i 6 szarżowników z Twardopięściów dla wielkiego szamana Rakjaka na Wzgórzu Szalonego Serca.$B$BJeśli zgubisz kajdany Goregeka, porozmawiaj ze starszym Harkekiem na Wzgórzu Szalonego Serca.', '', 'Wróć do wielkiego szamana Rakjaka na Wzgórzu Szalonego Serca w Kotlinie Sholazar.', '', '', '', '', 0),
(12530, 'koKR', 'Dręczenie miękkopięściów', 'Ej, niewolnicze coś!$B$BRakjak chcieć, żeby ja ciebie niańczyć, kiedy ja zabijać twardopięściów. Ja dziś hojny, to pozwolić tobie też kilku zabić, ale ty nie wchodzić Goregekowi w drogę!$B$BRakjak jeszcze nie wiedzieć, ale Goregek mieć oko na wielką złą mamę twardopięściów. My iść na Polanę Twardopięściów na wschodzie i szturchać miękkopięściów szturchaczem, a ona na pewno przybiec z wrzaskiem!$B$B<Goregek radośnie zaciera ręce.>', 'Goregek dał ci szturchacz na miękkopięściów, którym masz szturchać miękkopięściów, żeby wywabić z kryjówki matronę z Twardopięściów. Zabij matronę z Twardopięściów i zamelduj o jej śmierci wielkiemu szamanowi Rakjakowi na Wzgórzu Szalonego Serca.$B$BJeśli zgubisz kajdany Goregeka, porozmawiaj ze starszym Harkekiem na Wzgórzu Szalonego Serca.', '', 'Wróć do wielkiego szamana Rakjaka na Wzgórzu Szalonego Serca w Kotlinie Sholazar.', '', '', '', '', 0),
(12531, 'koKR', 'Podziemne zagrożenie', 'Pogromca lwów, ganiacz kur, $gnowy niewolnik:nowa niewolnica; Szalonego Serca...$B$BJa wiedzieć, że ty nie chcieć zostać $gniewolnik:niewolnica;, więc ja powiedzieć, co robić. Pokaż, że ty $glepszy:lepsza; niż inni łowcy Szalonego Serca, a wtedy Rakjak ciebie szanować.$B$BPod piaskami południowej rzeki być bestia, co zabijać osy, małpy, a nawet wolvary. Ona nazywać się Serfex. Ty zanieść pazur Serfexa do Rakjak, a może on uwolnić ciebie z niewoli.$B$BJa mieć nadzieję, że Dajik dobrze ciebie uczyć, to Serfex być łatwa sprawa.', 'Odszukaj Serfexa pod piaskami południowej rzeki, zabij go i zanieś jego pazur wielkiemu szamanowi Rakjakowi na Wzgórzu Szalonego Serca.$B$BJeśli zgubisz wytartą kredę Dajika, porozmawiaj ze starszym Harkekiem na Wzgórzu Szalonego Serca.', '', 'Wróć do wielkiego szamana Rakjaka na Wzgórzu Szalonego Serca w Kotlinie Sholazar.', '', '', '', '', 0),
(12532, 'koKR', 'Uciekły z kurnika!', 'Głupi Goregek wpaść do kurnika i wypuścić wszystkie kury!$B$BOne być na całym wzgórzu – ty iść złapać kury!$B$B<Starszy Harkek odgania cię machnięciem ręki.>', 'Złap 12 zbiegłych kur dla starszego Harkeka.$B$BJeśli zgubisz wytartą kredę Dajika, porozmawiaj ze starszym Harkekiem na Wzgórzu Szalonego Serca.', '', 'Wróć do starszego Harkeka na Wzgórzu Szalonego Serca w Kotlinie Sholazar.', '', '', '', '', 0),
(12533, 'koKR', 'Uczeń łowcy os', 'Rakjak nie głupi. Może ty $gdobry:dobra; w zabijaniu. Może Szalone Serce zrobić z ciebie $gprawdziwy łowca:prawdziwa łowczyni;.$B$BDajik polować na wielkie osy lepiej niż wszystkie wolvary. Ty iść z Dajikiem do Szafirowego Roju na południowym wschodzie albo nad rzekę na południu i uczyć się łowów.', 'Zabij 6 os z Szafirowego Roju i 9 trutni z Szafirowego Roju dla wielkiego szamana Rakjaka na Wzgórzu Szalonego Serca.$B$BJeśli zgubisz wytartą kredę Dajika, porozmawiaj ze starszym Harkekiem na Wzgórzu Szalonego Serca.', '', 'Wróć do wielkiego szamana Rakjaka na Wzgórzu Szalonego Serca w Kotlinie Sholazar.', '', '', '', '', 0),
(12534, 'koKR', 'Szafirowa Królowa', 'Jeżozwierze bywać groźne, ale większość trzymać się z dala od wolvarów. Za to osy nie bać się Szalonego Serca... one nawet zabić kilku naszych łowców.$B$BJa wiedzieć, że Rakjak chcieć śmierci królowej os, ale żaden wolvar nie chcieć iść do jej roju. Ty iść zabić królową os w Szafirowym Roju na południowym wschodzie i przynieść żądło dla Rakjak. Ja się założyć, że Rakjak to spodobać.', 'Zanieś żądło Szafirowej Królowej wielkiemu szamanowi Rakjakowi na Wzgórzu Szalonego Serca.$B$BJeśli zgubisz wytartą kredę Dajika, porozmawiaj ze starszym Harkekiem na Wzgórzu Szalonego Serca.', '', 'Wróć do wielkiego szamana Rakjaka na Wzgórzu Szalonego Serca w Kotlinie Sholazar.', '', '', '', '', 0),
(12535, 'koKR', 'Psota w przygotowaniu', 'Ty $gdobry łowca:dobra łowczyni;, ale Szalone Serce móc zrobić ciebie $gsilniejszym:silniejszą;. Harkek myśleć, że może ty $ggotowy:gotowa; na coś ważniejszego.$B$BZanim Rakjak wysłać ciebie na ważną misję, ty musieć zebrać rzeczy dla Rakjak. Wzdłuż całej rzeki na południu być niebieskie kryształy. Rakjak potrzebować dużo niebieskich kryształów.$B$BTy iść po kryształy teraz.', 'Wielki szaman Rakjak na Wzgórzu Szalonego Serca chce 8 skupisk kryształów Podniebnego Zasięgu.', '', 'Wróć do wielkiego szamana Rakjaka na Wzgórzu Szalonego Serca w Kotlinie Sholazar.', '', '', '', '', 0),
(12536, 'koKR', 'Wyboista jazda', 'Zepik najlepszy łowca Szalonego Serca. Zepik polować na wielkojęzorów... brzydkie stwory koło bagien, co próbować ukraść wszystko, co znaleźć.$B$BZepik iść na długą wyprawę rozbić kapliczkę wielkojęzorów i ich przestraszyć. My już nie chcieć wielkojęzorów w tej krainie.$B$BPo północno-wschodniej stronie wzgórza, koło drzewa, być przykuty krokoliszek – ty iść z Zepikiem i robić, co Zepik mówić.', 'Dojedź na uwięzionym krokoliszku do Schronienia Szeptu Mgły, a następnie porozmawiaj z Zepikiem, by otrzymać dalsze instrukcje.$B$BJeśli zgubisz róg myśliwski Zepika, porozmawiaj ze starszym Harkekiem na Wzgórzu Szalonego Serca.', 'Udaj się do Schronienia Szeptu Mgły.', 'Porozmawiaj z Zepikiem, łowcą gorloków. Jeśli nie ma go w pobliżu, możesz go przywołać rogiem myśliwskim Zepika.', '', '', '', '', 0),
(12537, 'koKR', 'Piorun jednak uderza dwa razy', 'Dobra, te kryształowe rzeczy...$B$BWielkojęzory używać kryształów do zasilania swoich kapliczek deszczu. Zepik nie wiedzieć dokładnie, jak to działać, ale Zepik wiedzieć, że jak one użyć złe kryształy, to chmury i deszcz wariować!$B$BZepik próbować zakraść się do jednej z ich innych kapliczek deszczu, ale nie pójść za dobrze. We dwóch na pewno pójść dużo lepiej!$B$BWeź kryształy, połóż przy wielkim kamiennym filarze-kapliczce, potem rozbij, żeby uwolnić moc. Zepik nie wiedzieć, co się stać, więc potem może lepiej się cofnąć.', 'Zepik chce, żebyś $grozbił:rozbiła; skupiska kryształów Podniebnego Zasięgu przed kapliczką pogody Szeptu Mgły.$B$BJeśli zgubisz róg myśliwski Zepika, porozmawiaj ze starszym Harkekiem na Wzgórzu Szalonego Serca.', 'Dokonaj sabotażu kapliczki pogody Szeptu Mgły', 'Porozmawiaj z Zepikiem, łowcą gorloków. Jeśli nie ma go w pobliżu, możesz go przywołać rogiem myśliwskim Zepika.', '', '', '', '', 0),
(12538, 'koKR', 'Mgła nie słucha', 'Goryle i osy nudne! Wielkojęzory jedyne, na co fajnie polować.$B$BJak my psuć kapliczkę deszczu, to my zabić dużo mglistych wielkojęzorów. Wtedy one na pewno nie chcieć wracać do tej swojej wioski.$B$B<Zepik z przekonaniem kiwa sam do siebie głową.>', 'Zepik chce, żebyś $gzabił:zabiła; 12 gorloków Szeptu Mgły.$B$BJeśli zgubisz róg myśliwski Zepika, porozmawiaj ze starszym Harkekiem na Wzgórzu Szalonego Serca.', '', 'Porozmawiaj z Zepikiem, łowcą gorloków. Jeśli nie ma go w pobliżu, możesz go przywołać rogiem myśliwskim Zepika.', 'Gorlok Szeptu Mgły', '', '', '', 0),
(12539, 'koKR', 'Na piechotę', 'Dobra, my skończyć! Czas wracać. Tym razem jednak nie ma krokoliszka do jazdy.$B$BJak my iść na wschód i trzymać się blisko grani, to ona zaprowadzić nas aż pod wzgórze.$B$BAle trzeba uważać, żeby nie zejść daleko pod grań, bo my wejść prosto do drzewnej wioski wielkojęzorów. Zepik nie myśleć, że one teraz nas lubić.', 'Wróć na Wzgórze Szalonego Serca i porozmawiaj z wielkim szamanem Rakjakiem.', '', '', '', '', '', '', 0),
(12540, 'koKR', 'Wykonuję tylko rozkazy', 'Dobra, $gkoleś:paniusiu;, Rakjak mieć bardzo ważne zadanie. Ty iść złapać rannego wielkojęzora, którego tropiciel wypatrzyć nad rzeką na północy.$B$BTym razem nie brać łowcy, bo on może chcieć go od razu zabić. Ja chcieć go schować, żeby móc go szturchać, aż on mi coś powiedzieć.$B$BIdź i przynieś mi wielkojęzorowe trofeum.', 'Odnajdź ranną wyrocznię Deszczomówców dla wielkiego szamana Rakjaka na Wzgórzu Szalonego Serca.$B', '', 'Porozmawiaj z ranną wyrocznią Deszczomówców na północ od Wzgórza Szalonego Serca w Kotlinie Sholazar.', 'Odnajdź ranną wyrocznię Deszczomówców', '', '', '', 0),
(12543, 'koKR', 'Dar dla Soo-rahma', 'My ciebie nie znać, $gobcy:obca;, ale my wiedzieć, że ty czegoś chcieć.$B$BMy porozmawiać za ciebie z Kośćmi Nozronna, ale ty musieć przynieść nam dary. My potrzebować potężnych kłów cesarskiej kobry, żeby dokończyć naszyjnik wyroczni.$B$BIdź do Dzikiego Namorzynu, na północny wschód od naszej chaty, znajdź kobry i przynieś najlepsze kły. Wtedy my sprawić, że kości przemówić do ciebie.', 'Przynieś 5 nienaruszonych kłów kobry wyroczni Soo-rahmowi przy Kościach Nozronna.', '', 'Wróć do wyroczni Soo-rahma w Kotlinie Sholazar.', '', '', '', '', 0),
(12544, 'koKR', 'Kości Nozronna', 'Kości Nozronna! Wyrocznia Soo-rahm przysyłać ci gościa – oto $N!$B$BMy przygotować dla ciebie kadzidło. Zapal je i połóż przy głowie Nozronna, a usłyszysz jego głos.$B$B<$GZmieszany:Zmieszana;, mówisz Soo-rahmowi, że nawet nie $gzadałeś:zadałaś; mu jeszcze pytania.>$B$BPrawda, my nie wiedzieć, ale potężny Nozronn wiedzieć. Nie wątpić. Nozronn odpowiedzieć na pytanie twojego serca.$B$BIdź. Nozronn nie czekać długo.', 'Użyj kadzidła Soo-rahma przy Kościach Nozronna, a potem wróć z tym, czego się $gdowiedziałeś:dowiedziałaś;, do Hemeta Nesingwary\'ego w Obozie Nesingwary\'ego.', '', 'Wróć do Hemeta Nesingwary\'ego w Obozie Nesingwary\'ego w Kotlinie Sholazar.', 'Odkryto kryjówkę Farunna', '', '', '', 0),
(12546, 'koKR', 'Odzyskanie ziem', 'Nadszedł czas, $N. Etymidian to jedna z najbardziej niszczycielskich sił, jakie kiedykolwiek stworzyli tytani, i niechętnie wypuszczam go na moje ziemie.$B$BNie mam jednak wielkiego wyboru. Wrogowie mnie do tego zmusili, a furia tytanów oczyści wszystko.', 'Udaj się do Lawiny w Kotlinie Sholazar i użyj runy omega, by uwolnić Etymidiana. Z jego pomocą zabij 200 sług Plagi, Bythiusa Rzeźbiarza Ciał, Urgretha Tysiąca Grobowców i Hailscorna.$B$BGdy wykonasz to zadanie, porozmawiaj z Awatarem Frei w Kotlinie Sholazar.', '', '', 'Zniszczone sługi Plagi', '', '', '', 0),
(12549, 'koKR', 'Łowy na szablobestie: droga drapieżnika', 'Jeśli już $gpolowałeś:polowałaś; z Hemetem, wiesz, że mierzył się z wieloma wielkimi kotami, ale straszliwe szablobestie z Sholazar są inne. Potrafią powalić większą zwierzynę, niż kiedykolwiek widziałem u polującego kota. Pokonać i zabić takiego drapieżnika to znak prawdziwego łowcy.$B$BJeśli chcesz dowieść, że podołasz wyzwaniu, zmierz się ze straszliwymi szablobestiami. Żyją w dziczy wokół obozu i na południe od rzeki.', 'Zabij 15 straszliwych szablobestii i wróć do Bucka Cantwella w Obozie Nesingwary\'ego.', '', 'Wróć do Bucka Cantwella w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12550, 'koKR', 'Łowy na szablobestie: na tropie ofiary', 'Słyszałem, że tubylcy opowiadają o wielkiej straszliwej szablobestii, którą nazywają Shango. Nie widziałem żadnych dowodów na istnienie tego Shango, ale przez obrażenia nie mogę się zapuszczać poza obóz.$B$BJeśli uważasz się za $gtropiciela:tropicielkę;, może uda ci się poznać prawdę o Shango. Debaar mówiła, że podczas ostatniej wyprawy widziała jakieś duże tropy. Idź na północ od obozu, w stronę Jeziora Gorzkiej Fali, i poszukaj odcisków łap na jego południowym brzegu.', 'Buck Cantwell w Obozie Nesingwary\'ego chce, żebyś wśród tropów straszliwych szablobestii nad Jeziorem Gorzkiej Fali $grozpoznał:rozpoznała; 3 tropy Shango.', '', 'Wróć do Bucka Cantwella w Obozie Nesingwary\'ego w Kotlinie Sholazar.', 'Rozpoznany trop Shango', '', '', '', 0),
(12551, 'koKR', 'Łowy na krokoliszki: sprawdzian', 'Ostrzegam cię, $gobcy:obca; – żadnych uwag o rozbiciu statku. Dość się tego nasłuchałam od reszty ekspedycji.$B$BJeśli jednak chcesz spróbować swoich sił w łowach, zmierz się z przebiegłymi krokoliszkami namorzynowymi. Żyją wzdłuż całej rzeki na południu i w Dzikim Namorzynie na wschodzie. Udowodnij, że potrafisz dać sobie z nimi radę, a wtedy znów porozmawiamy, $głowco:łowczyni;.', 'Zabij 15 krokoliszków namorzynowych i wróć do Debaar w Obozie Nesingwary\'ego.', '', 'Wróć do Debaar w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12556, 'koKR', 'Łowy na nosorożce: ubicie', 'Skoro wiemy już, gdzie znaleźć Farunna, pozostała tylko walka z tą wielką bestią. Jesteś $ggotów:gotowa; zmierzyć się z tym nosorożcem, $N? Mimo całego zadęcia tego ducha jestem pewien, że mówił prawdę o sile bestii.$B$BKiedy będziesz $ggotów:gotowa; stawić mu czoła, ruszaj na północ, za Filar Muśnięty Słońcem, i szukaj Farunna na północno-wschodnim brzegu Jeziora Gorzkiej Fali. Może się nawet zapuszczać w pobliże Połyskującego Filaru. Przynieś jego róg na pamiątkę zwycięstwa.', 'Zanieś róg Farunna Hemetowi Nesingwary\'emu w Obozie Nesingwary\'ego.', '', 'Wróć do Hemeta Nesingwary\'ego w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12558, 'koKR', 'Łowy na szablobestie: czas na skok', 'Shango czeka, $N. Jeśli tropienie ci się powiodło, nie będzie wiedział, że go podchodzisz, a ta przewaga będzie ci potrzebna.$B$BPodobno jest większy, silniejszy i groźniejszy od innych straszliwych szablobestii w kotlinie. Ruszaj na północ, na zachodni brzeg Jeziora Gorzkiej Fali, i w pobliżu zasilających je wodospadów stocz walkę z Shango. Jeśli ci się uda, wróć z jego futrem.', 'Zanieś futro Shango Buckowi Cantwellowi w Obozie Nesingwary\'ego.', '', 'Wróć do Bucka Cantwella w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12559, 'koKR', 'Zasilanie Wrót Przejścia – Grzęda Twórcy', 'A więc nadszedł czas. Aktywujmy Wrota Przejścia.$B$BPierwszy przełącznik znajdziesz wewnątrz Grzędy Twórcy, na zachodnim skraju kotliny.$B$BUważaj, $N. Tytani używali grzędy, by czuwać nad swoimi dziełami. Wciąż strzeże jej wielu ich kamiennych sług.', 'Awatar Frei przy Bystrzynie Deszczomówców chce, żebyś $gudał:udała; się do Grzędy Twórcy i $gużył:użyła; przełącznika aktywacyjnego gamma.', '', '', 'Przełącznik aktywacyjny gamma', '', '', '', 0),
(12560, 'koKR', 'Łowy na krokoliszki: plan', 'Krokoliszek namorzynowy jest mistrzem zasadzki, a ja zamierzam pokonać najlepszego w jego własnej grze. W tym celu musimy przygotować dla ciebie przekonujący kamuflaż. Wykorzystamy rośliny, które rosną w piaszczystej glebie nad brzegami rzek i na plażach jezior.$B$BNajlepsza do tego jest piaskopaproć. Rośnie na piaszczystych terenach nad brzegami Nurtu Morskiego Wyłomu, tuż na południu, Jeziora Gorzkiej Fali i Wodospadów Gorzkiej Fali na północy, a także na skraju Serca Rzeki, wielkiego jeziora za namorzynem na wschodzie.', 'Przynieś 5 liści piaskopaproci Debaar w Obozie Nesingwary\'ego.', '', 'Wróć do Debaar w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12561, 'koKR', 'Kwestia zaufania', 'To nigdy nie powinno było się wydarzyć. Siły nieumarłych szturmują samą kolebkę życia!$B$BJeśli nie przybywasz tu, by niszczyć sługi Króla Lisza, odejdź natychmiast. Nie ściągaj na siebie mojego gniewu, odciągając mnie od moich obowiązków.', 'Zdobądź zaufanie Frei, niszcząc 6 zarażonych zwłok i 10 pustoszycieli kościanej kosy na Zaginionych Ziemiach.', '', '', '', '', '', '', 0),
(12569, 'koKR', 'Łowy na krokoliszki: zasadzka', 'Największy krokoliszek w kotlinie, zwany tu „Krzakołazem” z racji mistrzostwa w zasadzkach, lubi wygrzewać się na płyciznach Serca Rzeki. To wielkie jezioro w środku kotliny, na wschód od naszego obozu.$B$BWeź kamuflaż, który przygotowałam, ukryj się na zachodniej plaży Serca Rzeki i zaatakuj Krzakołaza z zasadzki, gdy się pokaże. Jeśli zdołasz go pokonać, przynieś jego potężną szczękę.', 'Zanieś szczękę Krzakołaza Debaar w Obozie Nesingwary\'ego.', '', 'Wróć do Debaar w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12570, 'koKR', 'Szczęśliwe nieporozumienia', 'Ja przepraszać! Ja nie chcieć narobić ci kłopotów!$B$B<Ranna wyrocznia długo gapi się na ciebie bez wyrazu.>$B$BTy mnie uratować! My ci dziękować. My teraz wracać do wioski. Ty chodź też... ty móc zostać z nami! Pieskoludzie i tak trochę wredni.$B$BPowiedz, jak ty $ggotowy:gotowa; do drogi, dobrze?', 'Odprowadź ranną wyrocznię Deszczomówców do Baldachimu Deszczomówców i porozmawiaj z arcywyrocznią Soo-sayem.', 'Odprowadź ranną wyrocznię Deszczomówców do Baldachimu Deszczomówców', 'Porozmawiaj z arcywyrocznią Soo-sayem w Baldachimie Deszczomówców w Kotlinie Sholazar.', '', '', '', '', 0),
(12571, 'koKR', 'Niech zły wąż sobie pójdzie', 'My tu być długo przedtem, zanim przyjść pieskoludzie. To bardzo święte miejsce – my nie odejść.$B$BTy chyba może $gdobry:dobra;, ale my kazać Lafoo zostać z tobą, tak na wszelki wypadek. My myśleć, że ty rozumieć.$B$BTu być węże, co ciągle próbować zjeść nasze pisklęta. Idź z Lafoo i zrób, żeby one przestać, dobrze? Zwłaszcza ten wielki koło wodospadu na północnym wschodzie.', 'Arcywyrocznia Soo-say w Baldachimie Deszczomówców chce, żebyś $gzabił:zabiła; Jadokolca i 10 cesarskich kobr.$B$BJeśli zgubisz torbę na robaki Lafoo, porozmawiaj z arcywyrocznią Soo-sayem w Baldachimie Deszczomówców.', '', 'Wróć do arcywyroczni Soo-saya w Baldachimie Deszczomówców w Kotlinie Sholazar.', '', '', '', '', 0),
(12572, 'koKR', 'Bogowie lubią błyskotki', 'Soo-say powiedzieć, że my iść z tobą. Ty być $gmiły:miła;, dobrze?$B$BOoo, ooo! My wiedzieć! My móc ucieszyć Soo-saya, jak my przynieść więcej darów dla kapliczki! Nie trzeba iść daleko, koło wioski zawsze być coś do wykopania... tylko szukać iskierek w ziemi!$B$BIdziemy! Idziemy! Więcej darów dla kapliczki!', 'Zbierz 6 skarbów wykopanych przez Lafoo i zanieś je arcywyroczni Soo-sayowi w Baldachimie Deszczomówców.$B$BJeśli zgubisz torbę na robaki Lafoo, porozmawiaj z arcywyrocznią Soo-sayem w Baldachimie Deszczomówców.', '', 'Wróć do arcywyroczni Soo-saya w Baldachimie Deszczomówców w Kotlinie Sholazar.', '', '', '', '', 0),
(12573, 'koKR', 'Zawieranie pokoju', 'My mieć świetny pomysł. Ty być $gprzyjaciel:przyjaciółka; pieskoludzi, oni może ciebie posłuchać.$B$BMy chcieć, żebyś ty zanieść dar szamanowi Vekjikowi. On na południowym zachodzie, gdzie rzeka zmieniać się w wodospad. Powiedz pieskoczłowiekowi, że my nie chcieć walki. Powiedz, że my być grzeczni.$B$BTy $gdobry:dobra; $r. My ufać, że ty zrobić to dobrze.', 'Arcywyrocznia Soo-say w Baldachimie Deszczomówców chce, żebyś $gzaniósł:zaniosła; dar pokoju szamanowi Vekjikowi, a potem $gwrócił:wróciła; z jego odpowiedzią.$B$BJeśli zgubisz torbę na robaki Lafoo, porozmawiaj z arcywyrocznią Soo-sayem w Baldachimie Deszczomówców.', 'Przekaż dar pokoju szamanowi Vekjikowi', 'Wróć do arcywyroczni Soo-saya w Baldachimie Deszczomówców w Kotlinie Sholazar.', '', '', '', '', 0),
(12574, 'koKR', 'Już z powrotem?', '<Arcywyrocznia Soo-say przez chwilę wpatruje się w twoje czoło, zanim się odezwie.>$B$BSoo-gan prosić o pomoc. My myśleć, że pieskoludzie może znowu ich zaatakować.$B$BMy wysłać ciebie i Jaloota na pomoc... idźcie w górę zachodniej rzeki do Schronienia Szeptu Mgły. Rób, co Soo-gan mówi... bij pieskoludzi w nos, jak oni wredni, oni tego nie lubić.$B$B<Gdy odchodzisz, arcywyrocznia Soo-say znów wpatruje się w twoje czoło.>', 'Udaj się do Schronienia Szeptu Mgły i porozmawiaj z przywoływaczem mgieł Soo-ganem.$B$BJeśli zgubisz ulubiony kryształ Jaloota, porozmawiaj z arcywyrocznią Soo-sayem w Baldachimie Deszczomówców.', '', '', '', '', '', '', 0),
(12575, 'koKR', 'Zaginiony skarb Szeptu Mgły', 'Jacyś pieskoludzie przyjść i rozbić niebieskie kryształy przy Wielkim Kamieniu Mgły! Dużo deszczu i piorunów, i złych rzeczy... niebieski to zły kryształ dla Wielkiego Kamienia Mgły! Głupie pieskoludzie.$B$BPo piorunach pieskoludzie ukraść wielki skarb, co my znaleźć w morzu-jeziorze. My potrzebować skarbu z powrotem, żeby dać go Wielkiemu Kamieniowi Mgły! Kamień Mgły się gniewać po tym, co zrobić pieskoludzie!$B$BTen, co go zabrać, nazywać się Tarter... nie, Tiktak... nie, nie... Tartek. Tak, Tartek! On pójść do obozu na północy. Idź odzyskać skarb!', 'Zabij watażkę Tarteka i odzyskaj skarb Szeptu Mgły dla przywoływacza mgieł Soo-gana w Schronieniu Szeptu Mgły.$B$BJeśli zgubisz ulubiony kryształ Jaloota, porozmawiaj z arcywyrocznią Soo-sayem w Baldachimie Deszczomówców.', '', 'Wróć do przywoływacza mgieł Soo-gana w Schronieniu Szeptu Mgły w Kotlinie Sholazar.', '', '', '', '', 0),
(12576, 'koKR', 'Nie ma wyboru', 'My próbować być mili dla pieskoludzi, odkąd oni przyjść, ale oni tylko wredni.$B$BMy się nie gniewać, że oni głupi – oni nie robić dużo szkody. Ale teraz oni grzebać przy świętych kapliczkach. Przy świętych kapliczkach nie wolno grzebać. Wielkie Kamienie być tu od bardzo dawna, od kiedy Wielcy nas stworzyć.$B$BMy nie wiedzieć, co robić, jakby Wielki Kamień Mgły ucierpieć. Idź do ich obozu na północy... zrób, żeby pieskoludzie przestać i nie wracać!', 'Zabij 8 włóczników Szalonego Serca i 6 szabrowników Szalonego Serca dla przywoływacza mgieł Soo-gana w Schronieniu Szeptu Mgły.$B$BJeśli zgubisz ulubiony kryształ Jaloota, porozmawiaj z arcywyrocznią Soo-sayem w Baldachimie Deszczomówców.', '', 'Wróć do przywoływacza mgieł Soo-gana w Schronieniu Szeptu Mgły w Kotlinie Sholazar.', '', '', '', '', 0),
(12577, 'koKR', 'Czas do domu!', 'Ty $gdobry suchoskóry:dobra suchoskóra;. Szept Mgły bezpieczny, skarb bezpieczny, a pieskoludzie na pewno teraz dać nam spokój.$B$BTy wracać do Baldachimu Deszczomówców i powiedzieć Soo-sayowi, że ty się dobrze spisać.', 'Wróć do Baldachimu Deszczomówców.', '', '', '', '', '', '', 0),
(12578, 'koKR', 'Rozgniewany gorlok', 'Ja nie myśleć, że ty wrócić na czas, żeby znowu iść, ale ja się mylić. Ja wysyłać Moodle\'a do pobliskich przyjaciół Mchostąpów, żeby dać głupim Mchostąpom po głowie za to, że nie przychodzić do kapliczki. Ich wioska na wschodzie, w górę grani, na północny wschód od złamanego filaru.$B$BTy iść z Moodle\'em! On wyjątkowo mądry Deszczomówca... ty go dobrze słuchać.', 'Udaj się do Wioski Mchostąpów i po przybyciu porozmawiaj z Moodle\'em.$B$BJeśli zgubisz piłeczkę antystresową Moodle\'a, porozmawiaj z arcywyrocznią Soo-sayem w Baldachimie Deszczomówców.', 'Udaj się do Wioski Mchostąpów.', 'Porozmawiaj z Moodle\'em. Jeśli nie ma go w pobliżu, możesz go przywołać piłeczką antystresową Moodle\'a.', '', '', '', '', 0),
(12579, 'koKR', 'Krew życia dla kapliczki Mchostąpów', 'Zawsze podejrzewałem, że to głównie filary odpowiadają za naszą pogodę i odcięcie od nieumarłych... to w pewnym stopniu to potwierdza.$B$BNiedawno, gdy runął Filar Krwi Życia, rozległ się huk potężnej eksplozji. Pogoda u Mchostąpów zmieniła się niemal natychmiast... zaczął padać śnieg, a tego nigdy tu nie widujemy.$B$BZdołali powstrzymać śnieg, przynosząc więcej kryształów krwi życia do Wielkiego Kamienia Mchu. Może jeśli zrobimy to samo, pomoże to też odpędzić nieumarłych.', 'Moodle chce, żebyś $gzebrał:zebrała; 10 odłamków krwi życia, ale trzymaj się z dala od jaskini wewnątrz samego filaru.$B$BJeśli zgubisz piłeczkę antystresową Moodle\'a, porozmawiaj z arcywyrocznią Soo-sayem w Baldachimie Deszczomówców.', '', 'Porozmawiaj z Moodle\'em. Jeśli nie ma go w pobliżu, możesz go przywołać piłeczką antystresową Moodle\'a.', '', '', '', '', 0),
(12580, 'koKR', 'Wybawca Mchostąpów', 'Jest niewielka szansa, że nie wszyscy Mchostąpowie zginęli... a w najgorszym razie zasługują przynajmniej na to, żeby nie zarzynano ich w ten sposób.$B$BPomścijmy tę rzeź i przy okazji sprawdźmy, czy da się jeszcze kogoś uratować.', 'Moodle chce, żebyś $guratował:uratowała; 6 ofiar Mchostąpów w Wiosce Mchostąpów, choć niektórych może już nie dać się ocalić.$B$BJeśli zgubisz piłeczkę antystresową Moodle\'a, porozmawiaj z arcywyrocznią Soo-sayem w Baldachimie Deszczomówców.', '', 'Porozmawiaj z Moodle\'em. Jeśli nie ma go w pobliżu, możesz go przywołać piłeczką antystresową Moodle\'a.', 'Uratowane ofiary Mchostąpów', '', '', '', 0),
(12581, 'koKR', 'Brzemię bohatera', 'Może kryształy stopniowo odpędzą nieumarłych, ale trzeba zrobić jeszcze jedno.$B$BMusimy znaleźć przywódcę tych nieumarłych i go zabić, żeby nie było nikogo, kto znów pośle na nas tych nędzników. Jeśli moje podejrzenia są słuszne, jest gdzieś wewnątrz zwalonego filaru... Rozszczepionego Odłamka.$B$BZresztą wskazują na to zwłoki, które są tam wleczone.$B$BJa rozmieszczę odłamki i zaniosę wieści Soo-sayowi... ty w tym czasie musisz znaleźć inną pomoc.', 'Zabij Artruisa Bezdusznego.$B$BZdecydowanie zaleca się zapewnienie sobie pomocy przyjaciół, bo Moodle nie będzie mógł ci towarzyszyć w tym zadaniu.', '', 'Odzyskaj filakterię Artruisa w Rozszczepionym Odłamku.', '', '', '', '', 0),
(12582, 'koKR', 'Czempion Szalonego Serca', '', '', '', '', '', '', '', '', 0),
(12586, 'koKR', 'W poszukiwaniu większej zwierzyny', 'Cóż, $N, jak dotąd $gbyłeś:byłaś; dla ekspedycji ogromnym wsparciem. Debaar, Buck i ja nie zgromadzilibyśmy bez ciebie tak niesamowitej kolekcji trofeów.$B$BSłyszałem jednak, że w innych częściach kotliny żyją jeszcze groźniejsze potwory. Wysłałem na północ grupę zwiadowczą, żeby się zorientowała, jakie jeszcze bestie na nas czekają.$B$BChciałbym, żebyś do nich $gdołączył:dołączyła; i $gsprawdził:sprawdziła;, co znaleźli. Ruszaj na północ, za Jezioro Gorzkiej Fali, i poszukaj obozowiska.', 'Porozmawiaj z <x> w <x>.', '', '', '', '', '', '', 0),
(12589, 'koKR', 'Odrzut? Jaki odrzut?', 'Więc myślisz, że umiesz strzelać?$B$BNo to spróbujmy. Proszę, na początek dostaniesz coś miłego i łagodnego. Spokojnie, to nie ma żadnego odrzutu. Pamiętaj, nie celuj z tej broni w nic, do czego nie zamierzasz strzelić.$B$BA teraz, kiedy będziesz $ggotów:gotowa;, po prostu wyceluj w to jabłko na głowie starego Wilhelma Szczęściarza i ognia!', 'Za pomocą karabinu RJR zestrzel jabłko z głowy Wilhelma Szczęściarza, a potem porozmawiaj z Drostanem.', '', 'Wróć do Drostana w Obozie Nesingwary\'ego w Kotlinie Sholazar.', 'Zestrzelone jabłko z głowy Wilhelma Szczęściarza', '', '', '', 0),
(12592, 'koKR', 'Wyzwanie wielkiego łowcy', 'Więc masz w sobie coś z łowieckiego instynktu. Nieźle strzelasz, a Hemet cię nie przegonił, więc pewnie zamierza zabrać cię na łowy.$B$BCo powiesz na małe zawody, tylko ty i ja?$B$BHemet i reszta poproszą cię o pomoc w polowaniach. Przy okazji będziemy liczyć, ile zwierzyny każde z nas upolowało na ich potrzeby. Tego nie wygrasz w mgnieniu oka i przyjdzie ci zabijać najróżniejsze stworzenia. Powodzenia!', 'Zabij 60 sztuk zwierzyny łownej, pomagając Hemetowi i jego towarzyszom w polowaniach. Gdy zabijesz swoje 60, wróć do Drostana w Obozie Nesingwary\'ego, by porównać wyniki.', '', 'Wróć do Drostana w Obozie Nesingwary\'ego w Kotlinie Sholazar.', 'Zabita zwierzyna łowna', '', '', '', 0),
(12595, 'koKR', 'W poszukiwaniu większej zwierzyny', 'Cóż, $N, z pewnością $gdowiodłeś:dowiodłaś; swojej wartości jako $głowca:łowczyni; wszelkiej zwierzyny – nosorożców, kotów i krokoliszków. Niektórym członkom ekspedycji takie stworzenia wystarczą, by sprawdzić swoje łowieckie umiejętności, ale inni, tacy jak ja, łakną większych wyzwań.$B$BDorian Tropiciel Smoków ruszył na północ, za Jezioro Gorzkiej Fali, i rozbił tam obóz. Słyszał pogłoski o gigantycznych pradawnych smokach. Wyobraź sobie tylko, co to byłaby za zdobycz! Sprawdź, co u Doriana, i dowiedz się, czy mu się poszczęściło.', 'Porozmawiaj z Dorianem Tropicielem Smoków w Posterunku Doriana w Kotlinie Sholazar.', '', '', '', '', '', '', 0),
(12603, 'koKR', 'Ostrzenie szponów', 'Pradawne smoki zajmują większość terenów na północy i wschodzie, a żar ich oddechu czuję nawet z tej odległości. Zanim rzucimy wyzwanie najpotężniejszemu z nich, musimy sprawdzić swoje umiejętności na słabszych stworzeniach.$B$BMimo to nie trać czujności; każda z tych bestii może połknąć człowieka w całości. Gdy poznasz taktykę walki tych smoków, wróć, a powiem ci, co dalej.', 'Zabij 6 pradawnych smoków, a potem porozmawiaj z Dorianem Tropicielem Smoków w Posterunku Doriana.', '', 'Wróć do Doriana Tropiciela Smoków w Posterunku Doriana w Kotlinie Sholazar.', '', '', '', '', 0),
(12605, 'koKR', 'Zdobycie przynęty', 'Raczej nie zwrócimy uwagi matki miotu Sliviny, wymachując rękami jak głupcy, ale jeśli będziemy sprytni, zwabimy ją do walki. Przy okazji zdobędziemy więcej, eee, paszy dla mojego małego projektu.$B$B<Dorian zerka na Zootfizzle\'a.>$B$BAle na razie się tym nie przejmuj. Poszukaj jaj pradawnych smoków na terenach na wschód i północny wschód od obozu. Rozbij je i zgarnij pisklęta, które się wyklują. Kiedy matka miotu zorientuje się, co zrobiliśmy, nie będzie miała wyboru i stanie z nami do walki.', 'Przynieś 6 pradawnych piskląt Dorianowi Tropicielowi Smoków w Posterunku Doriana.', '', 'Wróć do Doriana Tropiciela Smoków w Posterunku Doriana w Kotlinie Sholazar.', '', '', '', '', 0),
(12607, 'koKR', 'Mamucie przedsięwzięcie', 'Zanim ruszysz do walki z matką miotu Sliviną, Dorian uznał, że dobrze byłoby, gdybyście ty i Hemet skoordynowali działania, ruszając do boju na grzbiecie mamuta.$B$BWokół obozu jest ich pełno. Weź tę uzdę i zarzuć ją na łeb mamuta Strzaskanego Kła. Uważaj jednak na samce. One w ogóle nie znoszą uprzęży. Kiedy znajdziesz odpowiedniego mamuta, przyprowadź go tutaj.', 'Przyprowadź mamuta Strzaskanego Kła do Zootfizzle\'a w Posterunku Doriana.', '', 'Wróć do Zootfizzle\'a w Posterunku Doriana w Kotlinie Sholazar.', 'Dostarczony mamut Strzaskanego Kła', '', '', '', 0),
(12608, 'koKR', 'Wtargnięcie kultystów', '<Wygląda na to, że słowa Awatara Frei się potwierdziły. Nieumarli nie mogli wejść do Kotliny Sholazar, zanim runął Filar Krwi Życia – zamiast tego posłużyli się swoimi żywymi agentami z Kultu Potępionych.>$B$B<Lepiej ostrzeż Awatara Frei przed żywymi agentami Króla Lisza w Kotlinie Sholazar.>', 'Porozmawiaj z Awatarem Frei przy Bystrzynie Deszczomówców.', '', '', '', '', '', '', 0),
(12611, 'koKR', 'Zwrócone siedmiokrotnie', 'Słudzy Króla Lisza w swej głupocie wtargnęli na ziemie, na których niepodzielnie panuje moc życia. Każda krzywda, którą wyrządzą, wróci do nich siedmiokrotnie.$B$BPotwór bezpośrednio odpowiedzialny za skażenie ziemi to Thalgran Zarazodzierżca; znajdziesz go nieco na północ stąd. Weź tę osłonę i użyj jej, by odbić na niego moc śmierci. Pokaż Pladze, że moc życia zwycięża wszystko.', 'Awatar Frei chce, żebyś $gpokonał:pokonała; Thalgrana Zarazodzierżcę, odbijając w niego za pomocą osłony Frei jego pociski śmierci ze siedmiokrotną siłą.', '', '', '', '', '', '', 0),
(12612, 'koKR', 'Zwalony filar', 'Tytani ukształtowali tu całe formy życia, wspierając ich nieskrępowany rozwój.$B$BPięć kryształowych filarów otaczających kotlinę emanuje czystą siłą życiową. Plaga nigdy nie powinna była zdołać wedrzeć się do kotliny, ale jeden z filarów został zniszczony.$B$BUdaj się do Filaru Krwi Życia i sprawdź, czy zdołasz ustalić, co się stało. Żaden nieumarły nie mógłby zbliżyć się do filaru, więc wypatruj żywych intruzów. To, co zostało z filaru, znajdziesz dokładnie na południe stąd.', 'Udaj się do Filaru Krwi Życia i poszukaj wskazówek, co doprowadziło do jego zniszczenia.', '', '', '', '', '', '', 0),
(12613, 'koKR', 'Zasilanie Wrót Przejścia – Punkt Widokowy Twórcy', 'Nie możemy teraz przestać, $N. $GUruchomiłeś:Uruchomiłaś; pierwszy przełącznik, ale został jeszcze jeden.$B$BTytani zbudowali drugi punkt obserwacyjny, z którego doglądali swoich dzieł. Znajdziesz go na wschodzie, wysoko w górach.$B$BPociągnij przełącznik aktywacyjny theta wewnątrz punktu widokowego, a Wrota Przejścia się otworzą.', 'Awatar Frei chce, żebyś $gudał:udała; się do Punktu Widokowego Twórcy we wschodniej części Kotliny Sholazar i $gużył:użyła; przełącznika aktywacyjnego theta.', '', '', 'Przełącznik aktywacyjny theta', '', '', '', 0),
(12614, 'koKR', 'Poporodowa agresja', 'Matka miotu Slivina będzie pewnie warczącym kłębkiem zębów, kolców i szponów. $GUkradłeś:Ukradłaś; jej dzieci, a żadna matka nie przyjmuje tego spokojnie.$B$BPrawda, wykluły się z jaj, ale kocha te małe bestie nie mniej niż twoja matka ciebie.$B$BBędzie w równym stopniu zdesperowana, co zaciekła – czyli ma wszystko, co Hemet kocha w zwierzynie. Ty i on, razem z tym mamutem, powinniście dać jej radę.$B$BCzeka na swojej grzędzie na północnym skraju Dzikiego Gąszczu i łaknie zemsty.', 'Zabij matkę miotu Slivinę i wróć do Doriana Tropiciela Smoków w Posterunku Doriana.', '', 'Wróć do Doriana Tropiciela Smoków w Posterunku Doriana w Kotlinie Sholazar.', '', '', '', '', 0),
(12617, 'koKR', 'Wytępić intruzów', 'Jestem ucieleśnieniem zaledwie jednego z aspektów Frei, córki tytanów. Jestem Strażniczką Życia – pozostawiono mnie tutaj, bym chroniła tę krainę przed Plagą.$B$BNigdy nie przypuszczałam, że Król Lisz przyśle żywych, chętnych sług, by wykonywali za niego robotę.$B$BZ łatwością sama zmiażdżyłabym tych kultystów, ale tylko ja stoję między armiami nieumarłych a resztą kotliny. Idź, $N. Zanieś mój gniew tym zuchwałym intruzom.', 'Awatar Frei przy Bystrzynie Deszczomówców chce, żebyś $gudał:udała; się do Obozowiska Ręki Śmierci na północnym zachodzie i $gzabił:zabiła; 8 kultystów infiltratorów.', '', '', '', '', '', '', 0),
(12620, 'koKR', 'Gniew Strażniczki Życia', 'Nie byliśmy dość szybcy, $N. Kultystyczne szumowiny dotarły do Połyskującego Filaru i przygotowują się do jego zniszczenia – wyczuwam ich.$B$BNie mamy wiele czasu. Zadmij w ten róg na szczycie Połyskującego Filaru, by przepuścić moją moc przez kryształ.$B$BPokażemy tym szumowinom, że z dziełami tytanów się nie igra.', 'Awatar Frei przy Bystrzynie Deszczomówców chce, żebyś $gużył:użyła; rogu Frei na szczycie Połyskującego Filaru.', '', '', 'Gniew Strażniczki Życia', '', '', '', 0),
(12621, 'koKR', 'Pakt Frei', 'Z kultystami się rozprawiono, ale inwazja Plagi nie zwalnia. Sytuacja staje się rozpaczliwa, $N.$B$BIstnieje ostatnia deska ratunku. Zanim jednak zdradzę więcej, muszę mieć pewność, że bezgranicznie mi ufasz.', 'Wysłuchaj, co ma do powiedzenia Awatar Frei.', '', '', 'Pakt Frei', '', '', '', 0),
(12624, 'koKR', 'Może być wszędzie!', 'Kiedy się dowiedziałem, że panna Boulian pomaga Nesingwary\'emu w ekspedycji, od razu zaciągnąłem się jako majtek. Widzisz, od miesięcy zbierałem się, żeby się z nią ożenić!$B$BMiałem wszystko zaplanowane. Zamierzałem się oświadczyć tej samej nocy, kiedy rozbił się statek... ale teraz pierścionek zniknął. Szukałem wszędzie!$B$BWiem, że to może brzmieć szalenie, ale wiem, że pierścionek zaręczynowy jest w kotlinie. Jeśli nie ukradł go ktoś ze spółki Gitgeszeft, to może połknęło go jakieś dzikie stworzenie. Ale jest tu gdzieś... po prostu to wiem!', 'Poszukaj złotego pierścionka zaręczynowego przy różnych stworzeniach w Kotlinie Sholazar.', '', 'Wróć do Chada w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12634, 'koKR', 'Jedni robią lemoniadę, inni nalewkę', 'Tym razem życie rzuciło mi całą furę cytryn! Kiedy statek osiadł na mieliźnie, beczki z moim najlepszym trunkiem popękały! Zostało nam tylko kilka butelek rumu, a to nie wystarczy spragnionej ekspedycji!$B$BMusimy zacząć coś pędzić, i to szybko!!$B$BDrzewa w Dzikim Namorzynie, na wschodzie, uginają się od owoców, ale rosną za wysoko, żebym dosięgnął. Poszukaj dobrych, mocnych pnączy i sprawdź, czy dasz radę nimi strząsnąć trochę owoców z drzew. Przynieś mi wszystko, co znajdziesz.', 'Przynieś 1 pomarańczę, 2 kiście bananów i 1 papaję Grimbooze\'owi Gromowarowi w Obozie Nesingwary\'ego.', '', 'Wróć do Grimbooze\'a Gromowara w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12644, 'koKR', 'Pędzimy dalej', 'Skoro mamy już surowce, kazałem pomocnikowi przygotować aparaturę. On będzie nadzorował proces, ale chcę, żebyś $gpomógł:pomogła; trzymać wszystko pod kontrolą. Może ci się wydawać, że wystarczy wrzucić wszystko do aparatury i czekać, ale to błąd.$B$BSkładniki i ciepło trzeba dodawać w określonych momentach, a w innych regulować ciśnienie. Na reakcję będziesz mieć nie więcej niż 10 sekund. Porozmawiaj z „Podchmielonym” McManusem, gdy będziesz $ggotów:gotowa; zacząć destylację.', 'Pomyślnie przeprowadź destylację i zanieś gotowy dżunglowy poncz Gromowarów Grimbooze\'owi Gromowarowi w Obozie Nesingwary\'ego.', '', 'Wróć do Grimbooze\'a Gromowara w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12645, 'koKR', 'Degustacja', 'A teraz chwila prawdy!$B$B<Grimbooze chichocze.>$B$BZawsze chciałem to powiedzieć. Zwykle nowy trunek prezentuję na bankiecie, ale w środku dżungli trudno taki wyprawić.$B$BZamiast tego zanieś próbki kilku zaufanym przyjaciołom i wróć z ich opiniami. Zobaczmy... na pewno chcemy poznać zdanie Hemeta Nesingwary\'ego, a także Hadriusa Harlowe\'a. Oni są tu, w obozie. Musisz też udać się na Przystań nad Jeziorem, niedaleko środka kotliny, i dać spróbować Tamarze Wobblesprocket.', 'Daj spróbować dżunglowego ponczu Gromowarów Hemetowi Nesingwary\'emu, Hadriusowi Harlowe\'owi i Tamarze Wobblesprocket, a potem wróć do Grimbooze\'a Gromowara w Obozie Nesingwary\'ego.', '', 'Wróć do Grimbooze\'a Gromowara w Obozie Nesingwary\'ego w Kotlinie Sholazar.', 'Degustacja Hemeta', 'Degustacja Hadriusa', 'Degustacja Tamary', '', 0),
(12651, 'koKR', 'Przystań nad Jeziorem', 'Kiedy zaczęły się kłopoty ze spółką Gitgeszeft, poprosiłem Marvina Wobblesprocketa i jego żonę Tamarę, żeby polecieli swoimi fruwającymi maszynami na wschód, do Serca Rzeki. Poprosiłem, żeby rozbili tam niewielki obóz, który posłuży nam za przekaźnik do dowożenia zapasów drogą powietrzną i badania okolicy.$B$BPowinni już tam dotrzeć i zacząć się urządzać. Serce Rzeki leży niedaleko środka kotliny, tam gdzie zbiegają się rzeki. Szukaj Przystani nad Jeziorem na północno-wschodnim brzegu. Marvin mówił, że to będzie najlepsze miejsce.', 'Porozmawiaj z Tamarą Wobblesprocket na Przystani nad Jeziorem.', '', '', '', '', '', '', 0),
(12654, 'koKR', 'Łowczyni na pół etatu', 'Kiedy Hemet poprosił mnie, żebym towarzyszyła tu Marvinowi, miałam nadzieję, że między naprawą fruwających maszyn a urządzaniem obozu znajdę okazję, by popracować nad własnymi umiejętnościami łowieckimi.$B$BChciałam upolować groźnego lwa imieniem Pitch. Podobno mieszka na południe stąd, tam gdzie Dziki Namorzyn styka się z północną ścianą Filaru Podniebnego Zasięgu. Jeśli znajdziesz tę bestię, przyniesiesz mi jej szczątki? Jeśli plotki są prawdziwe, byłoby z nich trofeum, które doceniłby nawet Hemet!', 'Zanieś szczątki Pitcha Tamarze Wobblesprocket na Przystani nad Jeziorem.', '', 'Wróć do Tamary Wobblesprocket na Przystani nad Jeziorem w Kotlinie Sholazar.', '', '', '', '', 0),
(12658, 'koKR', 'Mój pupil na cały rok', 'Dorian kazał mi szkolić i karmić młode smoki, które łapie, i dało mi to do myślenia. Chcę mieć własnego zwierzaka!$B$BNie, nie młodego smoka. Nie chcę pupila, który mógłby mi odgryźć rękę!$B$BZa to na Kościanych Polach na północny wschód od obozu, za terenami opanowanymi przez smoki, żyje mnóstwo krwawoszponych roków. Dorosłych nie da się już oswoić, ale jeśli przyniesiesz mi jaja z ich gniazd, wychowam je od wyklucia.', 'Przynieś 7 jaj roka Zootfizzle\'owi w Posterunku Doriana.', '', 'Wróć do Zootfizzle\'a w Posterunku Doriana w Kotlinie Sholazar.', '', '', '', '', 0),
(12660, 'koKR', 'Broń zniszczenia', 'Pachołkowie Króla Lisza ośmielili się wnieść broń zniszczenia do mojej domeny. Nie będę tego tolerować.$B$BUdaj się do ich posterunku na północy i zniszcz broń, której chcą użyć przeciw tej ziemi. Nie możemy pozwolić, by Plaga skaziła choćby piędź więcej tych świętych ziem.', 'Awatar Frei chce, żebyś $gudał:udała; się do Obozowiska Ręki Śmierci na północnym zachodzie i $gzniszczył:zniszczyła; 4 niestabilne materiały wybuchowe.', '', '', 'Zniszczone niestabilne materiały wybuchowe', '', '', '', 0),
(12671, 'koKR', 'Lot zwiadowczy', 'Najwyższy czas, żebyśmy mieli tu maszyny w powietrzu. Profesor prosi mnie, żebym sprawdził dziwne zjawisko pogodowe nadciągające z północnego wschodu.$B$BRzecz w tym, że jeśli mamy lecieć na niezbadane tereny, potrzebuję drugiego pilota. Za nic w świecie nie polecę tam sam.$B$BCo ty na to, $gtwardzielu:gwiazdo;? Może się czegoś nauczysz. A jak już nauczysz się radzić sobie z północnymi wiatrami... polecisz praktycznie wszędzie.', 'Pomóż pilotowi Vicowi ukończyć lot zwiadowczy.', 'Lot zwiadowczy', 'Porozmawiaj z pilotem Vicem na Przystani nad Jeziorem w Kotlinie Sholazar.', '', '', '', '', 0),
(12681, 'koKR', 'Agent do spraw składników', 'Ten arcymag Pentarus w Dalaranie będzie oczekiwał, że wrócimy z najróżniejszymi składnikami i talizmanami. Wygląda na to, że miejscowi przepadają za zwierzęcymi częściami. Wykrzywione szpony krwawoszponych roków należą do ich ulubionych.$B$BNie mnie oceniać, czy plotki są prawdziwe, ale mam przeczucie, że coś w tym jest.$B$BRoki żyją na Kościanych Polach na północnym wschodzie, gdzie żerują na zwłokach starych mamutów. Pomożesz mi zebrać szpony do badań arcymaga?', 'Przynieś 5 wykrzywionych szponów roka Colvinowi Norringtonowi w Posterunku Doriana.', '', 'Wróć do Colvina Norringtona w Posterunku Doriana w Kotlinie Sholazar.', '', '', '', '', 0),
(12683, 'koKR', 'Palę się do pomocy', 'W całej kotlinie nie ma bardziej żrącej substancji niż plwocina hydry z Gorzkiej Fali. Mam specjalne pojemniki, żeby zbierać właśnie coś takiego do badań arcymaga Pentarusa. Teraz potrzebuję tylko odważnego, eee... zbieracza.$B$BWyglądasz na kogoś $gwytrzymałego i żądnego:wytrzymałą i żądną; przygód. Co powiesz na to, żeby trochę zarobić i przy okazji wesprzeć sprawę Dalaranu?$B$BWystarczy, że weźmiesz ten pojemnik nad Jezioro Gorzkiej Fali, na południowym zachodzie. Zaatakuj hydry i użyj pojemnika, by pobrać próbki plwociny, którą będą cię obryzgiwać.', 'Colvin Norrington w Posterunku Doriana chce, żebyś $gpobrał:pobrała; 5 próbek plwociny hydry i $gzabił:zabiła; 5 hydr z Gorzkiej Fali.', '', 'Wróć do Colvina Norringtona w Posterunku Doriana w Kotlinie Sholazar.', 'Zebrane próbki plwociny', '', '', '', 0),
(12688, 'koKR', 'Inżynieria katastrofy', 'Te goblińskie zbiry i ich pachołki uznały, że ten filar i jego kryształy należą do nich. Przyszłam tu zbadać kryształy i pobrać próbki, ale mnie obezwładnili i nie pozwalają wrócić do obozu.$B$BJeśli pomożesz mi się stąd wyrwać, damy tym bandziorom nauczkę, której nigdy nie zapomną!', 'Pomóż inżynierce Helice uciec z Wykopaliska Swindlegrina, a potem porozmawiaj z Hemetem Nesingwarym w Obozie Nesingwary\'ego.', 'Wyprowadź inżynierkę Helice z Wykopaliska Swindlegrina', 'Wróć do Hemeta Nesingwary\'ego w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12689, 'koKR', 'Ręka Wyroczni', '', '', '', '', '', '', '', '', 0),
(12691, 'koKR', 'Wiekowa szkatuła', 'Kamienna szkatuła wydaje się zamknięta. Wygląda na to, że do dużego kamiennego otworu pasuje jakiś klucz.$B$BMoże któryś ze strażników w pobliżu ma ten klucz przy sobie.', 'Zdobądź ogromny kamienny klucz od pobliskich strażników z Sholazar i przynieś go do wiekowej szkatuły w Punkcie Widokowym Twórcy.', '', 'Wróć do wiekowej szkatuły w Punkcie Widokowym Twórcy w Kotlinie Sholazar.', '', '', '', '', 0),
(12692, 'koKR', 'Powrót Łowcy Liszy', 'Dobra, ja wracać na Wzgórze Szalonego Serca, żeby wszyscy z Szalonego Serca wiedzieć, co ty zrobić dla wolvarów i dla Zepika. Ty $gwielki łowca:wielka łowczyni;, a oni głupi, jak myśleć, że nie.$B$BWracaj na wzgórze i porozmawiaj ze starszym Harkekiem... ja dopilnować, żeby on wiedzieć, że ty nie $gzdrajca:zdrajczyni;, zanim dowiedzieć się inni z Szalonego Serca.$B$BDziękować, $gŁowco Liszy:Łowczyni Liszy;.', 'Wróć na Wzgórze Szalonego Serca i porozmawiaj ze starszym Harkekiem.', '', '', '', '', '', '', 0),
(12695, 'koKR', 'Powrót przyjaznego suchoskórego', 'Hura! Soo-say pewnie się o nas martwić! Może ty wrócić do wioski i powiedzieć mu, że wszystko dobrze? Tak, idź powiedzieć Soo-sayowi.$B$BJa zabrać błyszczącą kulkę od martwego lisza – spotkamy się tam! Idź, idź! Spotkamy się tam!', 'Wróć do Baldachimu Deszczomówców i porozmawiaj z arcywyrocznią Soo-sayem.', '', '', '', '', '', '', 0),
(12696, 'koKR', 'Zwiad z powietrza', 'Dobrze się $gspisałeś:spisałaś;, pomagając Wesowi naprawić tę fruwającą maszynę.$B$BJeśli chcesz nam dalej pomóc, z północnego wschodu nadciąga niezwykłe zjawisko pogodowe. Mam pilota gotowego do pracy, ale obawiam się, że potrzebuje drugiego pilota.$B$BJeśli uważasz, że dasz radę, możesz polecieć na Przystań nad Jeziorem. Powiedz Vicowi, że to ja cię przysłałam.', 'Profesor Calvert chce, żebyś $gpoleciał:poleciała; na Przystań nad Jeziorem i $gporozmawiał:porozmawiała; tam z pilotem Vicem.', '', '', '', '', '', '', 0),
(12699, 'koKR', 'Wstydliwy incydent', 'Zanim wyruszymy, musimy rozwiązać jeden mały problem. Widzisz, nie mogę znaleźć kluczyków do mojej fruwającej maszyny.$B$BSzukałem ich praktycznie wszędzie... może mi pomożesz. Jedyne miejsce, gdzie jeszcze nie szukałem, to jezioro.$B$BDam ci nawet mój własny zbiornik powietrza. Jest prawie pusty, ale zostało w nim jeszcze kilka wdechów.', 'Poszukaj kluczy Vica w wodach Serca Rzeki.', '', 'Wróć do pilota Vica na Przystani nad Jeziorem w Kotlinie Sholazar.', '', '', '', '', 0),
(12702, 'koKR', 'Kurza impreza!', 'Założę się, że ty nie zgadnąć, co się znowu stać.$B$BNie, nie Goregek ani kury.$B$BDobra, ja kłamać. Goregek znowu wypuścić kury. Głupi Goregek i jego burczący brzuch.$B$BPowiedz, jak ty potrzebować pomocy od któregoś z łowców... oni gdzieś tu być.', 'Złap 12 zbiegłych kur dla starszego Harkeka na Wzgórzu Szalonego Serca.', '', 'Wróć do starszego Harkeka na Wzgórzu Szalonego Serca w Kotlinie Sholazar.', '', '', '', '', 0),
(12703, 'koKR', 'Szał Kartaka', 'Ty $gwielki Łowca Liszy:wielka Łowczyni Liszy;, co? Dobrze mieć w bitwie tak silnego sojusznika Szalonego Serca. Może ty nawet $gdość silny:dość silna;, żeby przywołać Kartaka.$B$BWielka bitwa w Warowni Kartaka na południowym zachodzie. Idź zabijać iskrowe wielkojęzory, aż ty zdobyć dużo krwi wyroczni. Zanieś krew do ołtarza w Warowni Kartaka, żeby przywołać Kartaka na pyszną ucztę z wielkojęzorów.$B$BKartak zająć twoje ciało, jak ty $ggodny:godna;... z mocą Kartaka ty wyrżnąć więcej wielkojęzorów niż w najlepszych snach.$B$BIdź zabić dużo, $głowco:łowczyni;!', 'Zanieś czystą próbkę krwi wyroczni do Ołtarza Kartaka, by przywołać Kartaka. Dzięki mocy, którą Kartak się z tobą podzieli, zabij 50 pobliskich gorloków Iskrotkniętych dla szamana Jakjeka w Warowni Kartaka.', '', 'Wróć do szamana Jakjeka w Warowni Kartaka w Kotlinie Sholazar.', 'Zabite gorloki Iskrotkniętych', '', '', '', 0),
(12704, 'koKR', 'Przebłaganie Wielkiego Kamienia Deszczu', 'Odkąd Mchostąpów zaatakowano, ja się martwić, że może my nie być dobrzy dla Wielkiego Kamienia Deszczu... może my za bardzo chciwi. My potrzebować więcej skarbów na dary!$B$BTy ostatnio dobrze znajdować błyskotki... może ty poszukać więcej błyskotek koło wioski? Ty może potrzebować pomocy któregoś z dobrych Deszczomówców. Tylko powiedz, kogo.', 'Arcywyrocznia Soo-say w Baldachimie Deszczomówców chce, żebyś z pomocą towarzysza $gwykopał:wykopała; i $gzebrał:zebrała; 6 błyszczących skarbów.$B$BPorozmawiaj z arcywyrocznią Soo-sayem w Baldachimie Deszczomówców, by zapewnić sobie pomoc jednego z dawnych towarzyszy.', '', 'Wróć do arcywyroczni Soo-saya w Baldachimie Deszczomówców w Kotlinie Sholazar.', '', '', '', '', 0),
(12705, 'koKR', 'Wola tytanów', 'Pieskoludzie atakować Iskrotkniętych... my musieć walczyć, bo inaczej oni zaatakować też inne Wyrocznie.$B$BTy być dla nas $gdobry przyjaciel:dobra przyjaciółka;, więc może my dać ci specjalny zaszczyt. Wielcy dawno temu zostawić obrońcę dla kapliczek... on wciąż tu być, ale nie wiedzieć, że coś źle, póki ktoś nie ruszyć kapliczek.$B$BPieskoludzie tam na dole mieć złe kryształy do robienia kłopotów... zanieś zły kryształ do Kapliczki Błyskawic, żeby Soo-holu wiedzieć, że trzeba pomóc.$B$BNie bój się, jak Soo-holu zająć twoje ciało... on bardzo potężny, więc on cię chronić.', 'Zdobądź skażony kryształ od wolvarów w pobliżu Azylu Iskrotkniętych i zanieś go do Wielkiego Kamienia Błyskawic, by przywołać Soo-holu. Dzięki mocy, którą Soo-holu się z tobą podzieli, zabij 50 pobliskich wolvarów Szalonego Serca, a potem wróć do przywoływacza błyskawic Soo-meta przy Wielkim Kamieniu Błyskawic.', '', 'Porozmawiaj z przywoływaczem błyskawic Soo-metem w Azylu Iskrotkniętych w Kotlinie Sholazar.', 'Zabici napastnicy Szalonego Serca', '', '', '', 0),
(12726, 'koKR', 'Pieśń wiatru i wody', 'Słuchaj burzy, tak? Półka Burzotwórcy rozbrzmiewa pradawną pieśnią... Pieśnią wiatru i wody.$B$BWielka nawałnica pożera synów tajfunów i burz. Weź ten bęben i zagraj jego pieśń... zagraj pieśń Haiphoona.$B$BPomóż mu pożywić się wiatrem i wodą, żeby nawałnica mogła trwać.', 'Soo-nee chce, żebyś $gużył:użyła; bębnów nawałnicy na Półce Burzotwórcy i $gpomógł:pomogła; Haiphoonowi pożreć 3 zjawy burzy i 3 wodne duchy.', '', 'Wróć do wyroczni Soo-nee w Baldachimie Deszczomówców w Kotlinie Sholazar.', 'Pożarte wodne duchy', 'Pożarte zjawy burzy', '', '', 0),
(12732, 'koKR', 'Siła krwi z serca', 'Pewnego dnia Rejek być potężny wojownik. Krew i niebiański ogień uczynić Rejeka silnym. Ty niedługo zobaczyć.$B$BRejek dać ci fiolkę, ty zanieść na sam szczyt Filaru Muśniętego Słońcem, daleko na zachodzie. Nabrać tam wody do fiolki.$B$BPotem iść na północny skraj kotliny, na półkę skalną na północ od Kościanych Pól. Ty znaleźć i zabić matronę krwawoszponych roków. Wziąć krew z serca.$B$BTy połączyć krew z serca i wodę, przynieść do Rejeka. Rejek wypić, stać się silny.', 'Zanieś fiolkę krwi z serca muśniętej słońcem Rejekowi na Wzgórzu Szalonego Serca.', '', 'Wróć do Rejeka na Wzgórzu Szalonego Serca w Kotlinie Sholazar.', '', '', '', '', 0),
(12734, 'koKR', 'Rejek: pierwsza krew', 'Rejek właśnie zostać najmłodszy wojownik w całym plemieniu Szalonego Serca. Ojciec dać Rejekowi potężny miecz do pokonania wrogów Szalonego Serca, ale stara tradycja mówić, że miecz najpierw musieć zakosztować krwi. Zwykle to robić starszy wojownik. Ty zrobić Rejekowi ten zaszczyt?$B$BWeź ostrze, wbij w zwłoki wszystkich wrogów Szalonego Serca: os i twardopięściów na południowym zachodzie, i wielkojęzorów. Może splamić ostrze krwią Szeptu Mgły, daleko na północnym zachodzie, koło Jeziora Gorzkiej Fali.', 'Splam ostrze Rejeka krwią, wbijając je w zwłoki osy z Szafirowego Roju, szarżownika z Twardopięściów i 3 członków plemienia Szeptu Mgły. Możesz splamić miecz krwią wyroczni Szeptu Mgły albo wojowników Szeptu Mgły. Gdy wykonasz zadanie, wróć do Rejeka na Wzgórzu Szalonego Serca.', '', 'Wróć do Rejeka na Wzgórzu Szalonego Serca w Kotlinie Sholazar.', 'Ostrze splamione krwią osy z Szafirowego Roju', 'Ostrze splamione krwią szarżownika z Twardopięściów', 'Ostrze splamione krwią członków Szeptu Mgły', '', 0),
(12735, 'koKR', 'Pieśń oczyszczenia', 'Ziemia w Sholazar czysta. Filary chronić tę krainę od stuleci.$B$BWoda nie taka czysta, ona przychodzić spoza Sholazar... z oceanów, z jezior, z rzek. Woda czasem przynosić złe duchy – trzeba je oczyścić.$B$BWeź ten dzwonek i zagraj nad Jeziorem Gorzkiej Fali, nad Rzeką Zimościsku i przy Sercu Rzeki. To rozgniewać złego ducha... a wtedy ty musieć go zabić.', 'Soo-nee w Baldachimie Deszczomówców chce, żebyś $gzagrał:zagrała; na dzwonku oczyszczenia nad Jeziorem Gorzkiej Fali, nad Rzeką Zimościsku i przy Sercu Rzeki oraz $gzabił:zabiła; złe duchy, które nękają tamtejsze wody.', '', 'Wróć do wyroczni Soo-nee w Baldachimie Deszczomówców w Kotlinie Sholazar.', '', '', '', '', 0),
(12736, 'koKR', 'Pieśń zadumy', 'Oczywiście ty nie $gtaki mądry:taka mądra; jak gorlok! Ty tylko $gprosty:prosta; $r.$B$BAle ty nie $gbeznadziejny:beznadziejna;! Ty pokazać, że umieć się uczyć. Może kryształy zrobić cię $gmądrym:mądrą;, tak jak kryształy robić nas mądrymi!$B$BJa nauczyć cię grać pieśń, która oczyszcza umysł. Ty zagrać pieśń przy kryształach, a kryształy zrobić twój umysł lepszym... nie tak dobrym jak umysł gorloka, ale lepszym niż teraz. Filar Krwi Życia rozbity, ale inne filary wciąż dobre!', 'Soo-nee w Baldachimie Deszczomówców chce, żebyś $gużył:użyła; didgeridoo kontemplacji na szczycie Połyskującego Filaru, Filaru Muśniętego Słońcem, Filaru Mszystego Światła i Filaru Podniebnego Zasięgu.', '', 'Wróć do wyroczni Soo-nee w Baldachimie Deszczomówców w Kotlinie Sholazar.', 'Kontemplacja na Połyskującym Filarze', 'Kontemplacja na Filarze Mszystego Światła', 'Kontemplacja na Filarze Podniebnego Zasięgu', 'Kontemplacja na Filarze Muśniętym Słońcem', 0),
(12737, 'koKR', 'Pieśń płodności', 'Burza to niszczycielska siła. Burza pali drzewa. Burza zalewa domy.$B$BAle burza może też być siłą życia, jeśli znasz właściwą pieśń. Na Półce Burzotwórcy, nad Grzędą Twórcy, znajdziesz małe kopczyki ziemi. One bardzo żyzne – w środku kryją silne nasiono. Czekają tylko na właściwą pieśń.$B$BWeź ten róg i zagraj im pieśń.', 'Soo-nee w Baldachimie Deszczomówców chce, żebyś $gudał:udała; się na Półkę Burzotwórcy, na północny zachód od Grzędy Twórcy, i $gzagrał:zagrała; na rogu płodności przy 8 kopczykach nasiąkniętej żyznej ziemi.', '', 'Wróć do wyroczni Soo-nee w Baldachimie Deszczomówców w Kotlinie Sholazar.', 'Zagrana pieśń płodności', '', '', '', 0),
(12741, 'koKR', 'Siła nawałnicy', 'Głupie wielkojęzory myśleć, że śpiewanie do chmur dać im moc. Rejek pokazać wielkojęzorom, że moc się zdobywać, biorąc ją!$B$BDaleko na północnym zachodzie być duży, płaski teren, co wielkojęzory nazywać „Półka Burzotwórcy”. Rejek pewny, że tam da się dostać tylko lecąc jak ptak.$B$BRejek słyszeć, że na tej półce być potężne siły wiatru i wody. Zabij je za ich zło, potem zanieś to, co z nich zostać, do kapliczki wielkojęzorów, „Kapliczki Nawałnicy”, po zachodniej stronie półki. Rejek czekać na twój powrót z ostateczną mocą.', 'Zbierz 3 esencje monsunu i 3 esencje burzy i zanieś je do Kapliczki Nawałnicy. Wróć do Rejeka na Wzgórzu Szalonego Serca z prawdziwą mocą nawałnicy.', '', 'Wróć do Rejeka na Wzgórzu Szalonego Serca w Kotlinie Sholazar.', '', '', '', '', 0),
(12758, 'koKR', 'Nakrycie głowy bohatera', 'Rejek słyszeć opowieści o wielkich metalowych ludziach na dalekiej Półce Burzotwórcy. Daleko na północnym zachodzie, za krawędzią kotliny, ty ją znaleźć.$B$BWyobraź sobie Rejeka z głową wielkiego metalowego człowieka jako hełmem. Rejek nie do zatrzymania! Rejek potężny!$B$BTy zdobyć dla Rejeka, ale metalowa głowa może nie odpaść łatwo od metalowego ciała. Może ukraść bomby małym zielonym ludziom i ich przyjaciołom na Wykopalisku Swindlegrina koło Filaru Muśniętego Słońcem? Użyj bomb, żeby oderwać głowę od metalowego ciała, a potem przynieś do Rejeka.', 'Zdobądź materiały wybuchowe spółki Gitgeszeft od dowolnych członków spółki Gitgeszeft na Wykopalisku Swindlegrina i użyj ich, by zdobyć głowę Burzowida. Zanieś głowę Burzowida Rejekowi na Wzgórzu Szalonego Serca.', '', 'Wróć do Rejeka na Wzgórzu Szalonego Serca w Kotlinie Sholazar.', '', '', '', '', 0),
(12759, 'koKR', 'Narzędzia wojny', 'Zepik mówić mi, że ty może $gnajlepszy łowca:najlepsza łowczyni; gorloków, jakiego on spotkać... oprócz Zepika. Wciąż wielka bitwa na południowym zachodzie – ty iść pomóc.$B$BZepik trzymać w skrytce w Warowni Kartaka największe, najgorsze pułapki... on powiedzieć Vekgarowi, żeby ich użyć w bitwie, więc ty też ich użyj. Idź wybierz, jakie pułapki chcesz, i zabij dużo wielkojęzorów.$B$BDużo, dużo!', 'Weź kilka pułapek Zepika z jego skrytki w Warowni Kartaka. Za ich pomocą zabij 50 pobliskich gorloków Iskrotkniętych, a potem wróć do szamana Jakjeka w Warowni Kartaka.', '', 'Wróć do szamana Jakjeka w Warowni Kartaka w Kotlinie Sholazar.', 'Gorlok Iskrotkniętych', '', '', '', 0),
(12760, 'koKR', 'Sekretna siła Szalonego Serca', 'Bitwa w Warowni Kartaka wciąż trwać... ja myśleć, że czas, żebyś ty poznać wielki sekret Szalonego Serca.$B$BMy mieć jagody, co my przynieść z innych krain, skąd my przyjść... same nie takie specjalne, ale zmieszać je z pijanymi napojami, to one robić Szalone Serce super silnym. Ty teraz Szalone Serce... czas, żebyś ty też być $gsilny:silna;.$B$BJa dać ci trochę napoju, wtedy ty być super $gsilny:silna; i iść rozwalić wszystkie iskrowe wielkojęzory.', 'Za pomocą sekretnego napoju Szalonego Serca zabij 30 gorloków Iskrotkniętych wokół Warowni Kartaka.', '', 'Wróć do szamana Jakjeka w Warowni Kartaka w Kotlinie Sholazar.', 'Gorlok Iskrotkniętych', '', '', '', 0),
(12761, 'koKR', 'Mistrzostwo kryształów', 'Pieskoludzie wciąż atakować Iskrotkniętych... my myśleć, że oni może nie przestać, jak my ich nie zmusić. Ale my mieć sekretną broń... my wysłać ją do Soo-meta, żeby on jej użyć do ochrony wszystkich Wyroczni.$B$BSekretna broń być od samych Wielkich... wyjątkowo błyszczące kryształy znalezione w świętych świątyniach Wielkich. Bardzo uważaj... nie połamać ich.$B$BKryształy być w skrzyni koło kapliczki w Azylu Iskrotkniętych, daleko na południowym zachodzie. Ty iść użyć kryształów, żeby pomóc Soo-metowi pokonać pieskoludzi.', 'Zabierz kryształowe umocnienia z Azylu Iskrotkniętych i użyj ich, by zabić 50 pobliskich wolvarów Szalonego Serca. Gdy wykonasz zadanie, wróć do przywoływacza błyskawic Soo-meta w Azylu Iskrotkniętych.', '', 'Porozmawiaj z przywoływaczem błyskawic Soo-metem w Azylu Iskrotkniętych w Kotlinie Sholazar.', 'Napastnik Szalonego Serca', '', '', '', 0),
(12762, 'koKR', 'Moc Wielkich', 'My musieć coś zrobić, żeby pieskoludzie przestać atakować Azyl Iskrotkniętych. Jaloot przynieść mi bardzo specjalny kryształ, co on znaleźć w Sercu Rzeki... my widzieć tylko jeden taki wcześniej.$B$BKryształ teraz nie mieć mocy, ale otwarty Filar Krwi Życia powinien mieć energię, żeby go naładować, jak ty go tylko przybliżyć. Jak kryształ naładowany, idź do Azylu Iskrotkniętych daleko na południowym zachodzie i pozwól, żeby energia kryształu zrobić cię $gwielkim i silnym:wielką i silną;.$B$BWtedy czas skopać pieskoludziom tyłki.', 'Naładuj uśpiony wypolerowany kryształ przy odsłoniętym Filarze Krwi Życia. Udaj się do Azylu Iskrotkniętych i za pomocą mocy, którą daje kryształ, zabij 30 pobliskich wolvarów Szalonego Serca, a potem porozmawiaj z przywoływaczem błyskawic Soo-metem w Azylu Iskrotkniętych.', '', 'Porozmawiaj z przywoływaczem błyskawic Soo-metem w Azylu Iskrotkniętych w Kotlinie Sholazar.', 'Napastnik Szalonego Serca', '', '', '', 0),
(12803, 'koKR', 'Siła natury', 'Nie jestem pewien, co widziałem, lecąc na północny wschód, ale wyglądało mi to na gigantyczną kobietę, która skopała Pladze tyłek.$B$BSłyszałem, jak profesor mówiła o jakiejś „strażniczce życia”, którą tytani wyznaczyli, by czuwała nad Sholazar. Może nie jestem znawcą historii tytanów, ale wygląda na to, że to właśnie ona.$B$BWiem też, że jeśli Plaga przekroczy granicę między Zaginionymi Ziemiami a resztą Sholazar, nasza ekspedycja jest już martwa. Co powiesz na to, żeby jej poszukać i podać jej pomocną dłoń?', 'Udaj się na Linię Zarazy, między Bystrzyną Deszczomówców a Zaginionymi Ziemiami w Kotlinie Sholazar, i odszukaj Awatara Frei.', '', '', '', '', '', '', 0),
(12804, 'koKR', 'Stek godny łowcy', 'Czasem nie ma nic gorszego niż obóz pełen łowców. Wszyscy są tak zajęci ubijaniem zwierzyny, że dostaję tylko twarde, żylaste mięso. A to nie jest coś, na co ma się ochotę po powrocie z długiego dnia polowania.$B$BNa szczęście w pobliżu jest źródło delikatnego, soczystego mięsa. Na południe od rzeki i obozu żyją długoszyi trawożercy. To idealne źródło mięsa dla naszych głodnych łowców. Przynieś mi najlepsze kawałki, a porządnie uczcimy naszych towarzyszy.', 'Przynieś 5 steków z długoszyjego trawożercy Korgowi Tasakowi w Obozie Nesingwary\'ego.', '', 'Wróć do Korga Tasaka w Obozie Nesingwary\'ego w Kotlinie Sholazar.', '', '', '', '', 0),
(12805, 'koKR', 'Ocalić siłę życia', 'Filar Krwi Życia został obalony z wielką siłą, która wstrząsnęła samą ziemią.$B$BŻywiołaki błąkające się po Rozszczepionym Odłamku niosą w sobie tę samą esencję życia, która dawała filarowi siłę. Nie mogę pozwolić, by ta energia się zmarnowała, bo zostały już tylko cztery filary.$B$BUdaj się do Rozszczepionego Odłamka, na południowym wschodzie, i odszukaj żywiołaki krwi życia.$B$BUżyj tego klejnotu na ich szczątkach, by odzyskać ich rozszalałą energię. Będziemy jej potrzebować, by uleczyć tę ziemię, gdy to wszystko się skończy.', 'Awatar Frei chce, żebyś $gudał:udała; się do Rozszczepionego Odłamka na południowym wschodzie i $gużył:użyła; klejnotu siły życiowej na 8 zniszczonych żywiołakach krwi życia.', '', '', 'Odzyskana energia krwi życia', '', '', '', 0),
(13052, 'koKR', 'Zwiad z powietrza', 'Dobrze się $gspisałeś:spisałaś;, pomagając Wesowi naprawić tę fruwającą maszynę.$B$BJeśli chcesz nam dalej pomóc, z północnego zachodu nadciąga niezwykłe zjawisko pogodowe. Mam pilota gotowego do pracy, ale obawiam się, że potrzebuje drugiego pilota.$B$BJeśli uważasz, że dasz radę, możesz polecieć na Przystań nad Jeziorem. Powiedz Vicowi, że to ja cię przysłałam.', 'Profesor Calvert chce, żebyś $gpoleciał:poleciała; na Przystań nad Jeziorem i $gporozmawiał:porozmawiała; tam z pilotem Vicem.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(12489, 'koKR', 'Ha! Nieczęsto w środku dżungli wpada się na kogoś zupełnie obcego.$B$BJesteś $gjednym:jedną; z tych druidzkich pachołków, co mieli „powstrzymać mnie i moje niecne praktyki”? No, to powodzenia!$B$B<Hemet wybucha serdecznym śmiechem i klepie swoją strzelbę.>$B$BTak myślałem! Chętnie przyjmiemy cię na łowy, jak tylko rozprawimy się z tymi psami ze spółki Gitgeszeft. Zwierzyny starczy dla wszystkich.', 0),
(12520, 'koKR', 'No, no, no, wygląda na to, że jednak $gprzeżyłeś:przeżyłaś; spotkanie z nosorożcami, i to w całkiem niezłej formie, jeśli wolno mi zauważyć. Ale polowanie na nosorożce to coś więcej niż patrzenie szarżującej bestii w oczy z nadzieją, że celnie trafisz. O nie, będziesz potrzebować czegoś więcej, żeby zmierzyć się z nosorożcowym patriarchą, który podobno żyje w tej dżungli.', 0),
(12521, 'koKR', 'Tak, Hemet tu jest. Siedzi w obozie, idź na północny zachód w stronę rzeki, a zaraz go zobaczysz. I na miłość Światłości, $gchłopcze:dziewczyno;, niech przyśle kogoś, żeby mnie stąd odciął!', 0),
(12522, 'koKR', 'Tam... po prostu postaw go tam. Ostrożnie! Jeśli zniszczysz i ten, będziemy mieli poważne kłopoty. No, zobaczmy, co da się zrobić.', 0),
(12523, 'koKR', 'Przy odrobinie pracy powinny wystarczyć. Choć moja biedna fruwająca maszyna może w końcu bardziej przypominać rozdrabniacz spółki Gitgeszeft. Biedaczka będzie musiała poczekać, aż wrócimy do Dalaranu, żeby odzyskać swój właściwy kształt.', 0),
(12524, 'koKR', 'To powinno utrudnić im działalność, ale obawiam się, że brygadzista spróbuje ściągnąć więcej robotników. Musimy dokończyć robotę, póki możemy.', 0),
(12525, 'koKR', 'Co za ulga słyszeć, że spółka Gitgeszeft nie będzie nas już nękać. Dziękuję ci w imieniu swoim i Hemeta, że $gzająłeś:zajęłaś; się tym problemem. Łowczyni nie może z czystym sumieniem podnieść broni na drugiego człowieka.', 0),
(12526, 'koKR', 'Co cię sprowadza do kapliczki Rahma?', 0),
(12528, 'koKR', 'Ty $gnowy niewolnik:nowa niewolnica;?$B$BDobrze. Nam się kończyć.', 0),
(12529, 'koKR', 'Goregek pokazać $ggłupi niewolnik:głupia niewolnica; $r, jak to się robić.', 0),
(12530, 'koKR', 'Goregek zabrać ciebie zabić wielką mamę twardopięściów, co? Ty mieć szczęście!$B$BGłupie miękkopięści ładnie kwiczeć!$B$B<Rakjak głośno kwiczy i wybucha śmiechem.>', 0),
(12531, 'koKR', 'Ty zabić Serfex? Ja się założyć, że ty iść za potężny wolvar, co zabić Serfex, a ty tylko zabrać pazur.$B$BTeraz to mój pazur.', 0),
(12532, 'koKR', 'Dobrze! Ja się martwić o jedzonko. Ja już bardzo głodny.$B$BDziękować, $r.', 0),
(12533, 'koKR', 'My zabić dużo, dużo os.$B$BRakjak nie myśleć, że one się skończyć.', 0),
(12534, 'koKR', 'Ty zabić królową os! Ty $gsilniejszy:silniejsza;, niż Rakjak myśleć.$B$BMoże teraz osy odejść i przestać atakować łowców Szalonego Serca.', 0),
(12535, 'koKR', '$GDobry:Dobra; $r! Dobrze, wszystko gotowe.', 0),
(12536, 'koKR', 'My tu! Musieć działać szybko.$B$BUważać na wielkojęzorów.', 0),
(12537, 'koKR', 'To działać tak dobrze!$B$BTy widzieć, jak piorun trzasnąć tego gościa-wyrocznię? Tak dobrze!$B$B<Zepik zaciera ręce i chichocze jak szaleniec.>', 0),
(12538, 'koKR', 'Ja dobrze podziurawić te wielkojęzory.$B$BTy chyba też być w porządku.$B$BNie, ja tylko żartować! Ty $gdobry łowca:dobra łowczyni;. Ja się cieszyć, że polować z tobą.', 0),
(12539, 'koKR', '$GWysadzony:Wysadzona; przez piorun?$B$B<Rakjak na chwilę wybucha śmiechem.>$B$BTy $gdobry łowca:dobra łowczyni;. Rakjak ciebie lubić. Może kiedyś ty zostać $ghonorowy członek:honorowa członkini; Szalonego Serca!$B$BAle tylko może!', 0),
(12540, 'koKR', 'Nie zabijać mnie, proszę! My tylko szukać ryb. My nie chcieć umierać.', 0),
(12543, 'koKR', '<Wyrocznia ogląda kły.>$B$BMy aprobować! $N usłyszeć głos Kości Nozronna!', 0),
(12544, 'koKR', '<Hemet słucha, jak opisujesz, czego się $gdowiedziałeś:dowiedziałaś;.>$B$BBrawo, $gchłopcze:dziewczyno;. Żaden martwy nosorożec nie będzie mówił Hemetowi Nesingwary\'emu, gdzie i na co może polować. Pokażemy tej kupie kości.', 0),
(12546, 'koKR', 'Jestem ci wdzięczna za pomoc, $N. Moim obowiązkiem jest czuwać nad tymi ziemiami i nad wszelkim życiem, które je zamieszkuje.$B$BDzięki tobie to życie będzie dalej kwitnąć, podczas gdy w sąsiednich krainach szaleją siły śmierci.$B$BTwoje czyny nie zostaną zapomniane.', 0),
(12549, 'koKR', 'No, $gdowiodłeś:dowiodłaś;, że z ciebie $gsprawny łowca:sprawna łowczyni;, ale jak radzisz sobie z tropieniem?', 0),
(12550, 'koKR', 'Chyba $gznalazłeś:znalazłaś; dowód na istnienie Shango, którego potrzebowaliśmy. I chyba mam pomysł, gdzie możemy go znaleźć.', 0),
(12551, 'koKR', 'Imponujące, $N. Na pewno nie jesteś członkiem ekspedycji?$B$BNie, jestem tego pewna. Gdzieś by się tu wkradł żart o katastrofie.', 0),
(12556, 'koKR', '<Hemet ogląda róg.>$B$BZdumiewające trofeum po niezwykłym zwierzęciu! $N, dochodzą mnie słuchy o jeszcze większej i groźniejszej zwierzynie na północnych rubieżach kotliny i chciałbym, żebyś $gpomógł:pomogła; nam ją wytropić.', 0),
(12558, 'koKR', 'Cóż za wyborne futro z tak szlachetnego zwierzęcia! Raduje mnie, że plotki o Shango okazały się prawdą, $N. Twój pościg za tym stworzeniem był bezbłędny. Jesteś $gprawdziwym myśliwym:prawdziwą myśliwą;.', 0),
(12559, 'koKR', 'Jesteśmy w połowie drogi, $N. Trzeba aktywować jeszcze jeden przełącznik, zanim będziemy mogli sprowadzić Etymidiana.', 0),
(12560, 'koKR', '<Debaar bierze od ciebie liście piaskopaproci i zaczyna oplatać je wokół twojego ciała.>$B$BTak, to powinno zadziałać. Nie ruszaj się! Jeszcze zrobimy z ciebie krzak.', 0),
(12561, 'koKR', 'Dobrze więc, $N. Jestem przekonana, że nie należysz do sług Króla Lisza... może jednak jest coś, co możesz dla nas zrobić.', 0),
(12569, 'koKR', '<Debaar słucha, jak opowiadasz o tym, że przebranie zawiodło.>$B$BJak to, nasz plan nie zadziałał tak, jak powinien?$B$BCóż, trzeba ci przyznać, że udało ci się go ubić. Spójrz tylko na rozmiar tej szczęki! Hemet będzie dumny z naszych starań. Ten krokoliszek był prawdziwym potworem.', 0),
(12570, 'koKR', 'Ty nam pomóc? To ty mile $gwidziany:widziana;, $N.', 0),
(12571, 'koKR', 'Węża nie ma?$B$B$GDobry:Dobra; $r. My dziękować.', 0),
(12572, 'koKR', 'Błyskotki dla Wielkiego Kamienia Deszczu! Dobrze! Dobrze!$B$BMy je zaraz ofiarować. To Lafoo wymyślić, tak? On bardzo mądry Deszczomówca.', 0),
(12573, 'koKR', 'Jacy wredni! My tylko miłe, a oni tylko wredni.$B$BOni ciągle grzebać przy wielkich kamieniach... może oni nie wiedzieć, że wielkie kamienie święte.', 0),
(12574, 'koKR', 'My myśleć, że my ciebie już widzieć. Ty już kiedyś odwiedzać wioskę Szeptu Mgły?$B$BSoo-say mówić, że ty $gdobry:dobra;. Soo-say mądry, więc my też ci ufać.$B$B<Przywoływacz mgieł Soo-gan obdarza cię niezręcznie szerokim uśmiechem.>', 0),
(12575, 'koKR', 'Ty to zrobić! Ty $gsilny i miły:silna i miła;! $GDobry przyjaciel:Dobra przyjaciółka; Szeptu Mgły!$B$B<Przywoływacz mgieł Soo-gan szczerzy wszystkie zęby w szerokim uśmiechu.>', 0),
(12576, 'koKR', 'Ty dobrze zgniatać. Dziękować za pomoc.', 0),
(12577, 'koKR', 'Ty już z powrotem!$B$BWięc poszło dobrze, tak?', 0),
(12578, 'koKR', 'Zanim cokolwiek powiesz: nie bierz mnie za takiego głupca jak większość Wyroczni, które $gpoznałeś:poznałaś;. Trochę już widziałem świata, nauczyłem się waszego języka i niełatwo mnie oszukać.$b$bWiedziałem, że Mchostąpowie nie żyją, zanim tu przyszliśmy, choć nie wiedziałem, że stoją za tym nieumarli.$b$bNie powinni móc wejść do tej krainy... to zniszczenie Filaru Krwi Życia musiało ich jakoś wpuścić. Musimy dopilnować, żeby się stąd wynieśli.', 0),
(12579, 'koKR', 'Może już za późno, żeby odłamki coś zmieniły, ale nie mamy zbyt wielu możliwości.', 0),
(12580, 'koKR', 'Bardzo się cieszę, że niektórych udało się uratować... przy odrobinie szczęścia bezpiecznie dotrą do Baldachimu Deszczomówców.', 0),
(12581, 'koKR', '<Wewnątrz filakterii Artruisa widzisz coś, co wygląda jak bezkresna pustka... i wydaje ci się, że gdzieś w jej głębi słychać odległe krzyki.>$b$b<Gdy już masz odejść, dostrzegasz przedmiot unoszący się w pustce, ledwie w zasięgu ręki.>', 0),
(12582, 'koKR', 'Ja wiedzieć, że ty nie być $gzdrajca:zdrajczyni;, jak inni mówić. My polować razem... ja znać ciebie lepiej niż oni wszyscy. Dziękować, że ty mnie uratować.$b$bTo może brzmieć śmiesznie... ja nie przepadać za wielkojęzorami... ale nawet mi trochę przykro, że wielkojęzor tak zginąć... uczciwa walka dużo lepsza... one walczyć dość dobrze, żeby zasłużyć na uczciwą walkę.$b$bTy chcieć znowu przyjaźnić się z Szalonym Sercem? Ja myśleć, że ja ich przekonać, że ty mnie uratować i dobrze załatwić wielkojęzorów. Ale ja nie chcieć, żeby przez ciebie ja wyjść na głupka, więc ty $gpewny:pewna;?', 0),
(12589, 'koKR', 'Nieźle strzelasz, a z praktyką będzie jeszcze lepiej. Co powiesz na mały zakład?', 0),
(12592, 'koKR', 'Co, już $gprzyszedłeś:przyszłaś; się poddać?$b$b<Drostanowi opada szczęka, gdy mówisz mu, że masz już na koncie wszystkie łupy.>$b$bNiemożliwe! Jak, na Azeroth, tego $gdokonałeś:dokonałaś;? Ja właśnie ubiłem 58. sztukę. Tak blisko!$b$bAle uczciwość przede wszystkim. Nie doceniłem cię, $N, ale to zwycięstwo $gzdobyłeś:zdobyłaś; uczciwie.', 0),
(12595, 'koKR', 'Czyli stary Hemet jednak o mnie nie zapomniał. Pewnie będzie chciał się przyłączyć do łowów, jak już odwalimy całą ciężką robotę. Spokojnie, smoków starczy dla wszystkich. Hemet dostanie, czego chce.', 0),
(12603, 'koKR', 'Słyszę pewność w twoim głosie. Dobrze, to doświadczenie przyda się, gdy staniemy przed królową smoków.', 0),
(12605, 'koKR', 'Ach, dobra robota. Mnóstwo małych piskląt dla Zootfizzle\'a!', 0),
(12607, 'koKR', 'Idealnie! Teraz trzeba już tylko załatwić Hemetowi drabinkę...', 0),
(12608, 'koKR', 'Żywi... dobrowolnie służą Królowi Liszowi?$b$bPrzez cały ten czas szukałam niewłaściwego wroga, $N. Pospieszmy się i wyplenijmy tych kultystów z tych ziem.', 0),
(12611, 'koKR', 'Wciąż udowadniasz swoją wartość, $N. Może zbyt pochopnie cię oceniłam.$b$bZakładałam, że $gprzybyłeś:przybyłaś; tu z kłusownikami, którzy niedawno utknęli na moich ziemiach, ale może jesteś $ggotów:gotowa; zostawić to za sobą.', 0),
(12612, 'koKR', '<Zwłoki są mocno spalone. W pobliżu widać szczątki kilku beczek prochu.>', 0),
(12613, 'koKR', 'Wrota Przejścia są aktywne, $N. Nadszedł czas!', 0),
(12614, 'koKR', 'Cóż, miałem przygotowaną całą przemowę, ale sam stary chce ci coś powiedzieć.', 0),
(12617, 'koKR', 'Mówisz prawdę. Z intruzami w obozie się rozprawiono... ale obawiam się, że mogło być już za późno.', 0),
(12620, 'koKR', 'Imponujące. Nie spodziewałam się, że $gzwykły śmiertelnik okaże się tak godnym sojusznikiem:zwykła śmiertelniczka okaże się tak godną sojuszniczką;.$b$bObawiam się jednak, że nasze wysiłki nie wystarczyły. Plaga ani myśli się zatrzymać.', 0),
(12621, 'koKR', 'Nie ma już odwrotu. Jeśli zgodzisz się mi pomóc, zrobisz to bez wahania.', 0),
(12624, 'koKR', 'Udało ci się! Naprawdę go $gznalazłeś:znalazłaś;!$B$BNie wiem... nie wiem, jak ci dziękować!', 0),
(12634, 'koKR', 'No, to lepszy wybór, niż się spodziewałem po tym miejscu. A teraz najważniejsze pytanie: czy da się z tego wydestylować coś zdatnego do picia? Lepiej zabierzmy się do roboty.', 0),
(12644, 'koKR', '<Grimbooze potrząsa beczułką.>$b$bCoś tu jest, ale pytanie za milion sztuk złota brzmi: czy da się to pić? Nigdzie się nie ruszaj; ty też będziesz odpowiadać za nadzór nad degustacją produktu.', 0),
(12645, 'koKR', 'Dwóch na trzech pijących jest za, co? Nieźle jak na pierwszą próbę. Wcale nieźle. Chyba będę musiał przyrządzić coś innego dla Tamary na przeprosiny.$b$bA teraz... jak nazwiemy to dzieło?', 0),
(12651, 'koKR', 'Więc to Hemet cię przysłał? Właśnie mieliśmy mu dać znać, że wszystko już tu działa. Wybacz Marvinowi, jeśli będzie sprawiał wrażenie, że cię ignoruje, ale praca zupełnie go pochłania.', 0),
(12654, 'koKR', 'Masz je! Teraz muszę tylko zrobić z nich trofeum. To będzie najtrudniejsze – znaleźć sposób, żeby je zakonserwować tak, by Hemet nie uśmiał się moim kosztem.', 0),
(12658, 'koKR', 'Och, są bardzo ładne! Mam już dość towarzystwa mechanicznych wiewiórek i kur. Wspaniale będzie mieć zwierzaka, któremu nie trzeba oliwić stawów!', 0),
(12660, 'koKR', 'Dziękuję ci, $N. Okazujesz się $ggodnym sojusznikiem:godną sojuszniczką;.', 0),
(12671, 'koKR', '$GUratowałeś:Uratowałaś; mi tam życie, $gkolego:koleżanko;. Niezłe latanie!', 0),
(12681, 'koKR', '<Colvin z podziwem przygląda się przyniesionym szponom.>$b$bTe w zupełności wystarczą. Gorloki mają powiedzenie, że im bardziej sękaty szpon, tym więcej mocy w sobie kryje. Jestem pewien, że arcymag nie pożałuje pieniędzy wydanych na tę ekspedycję.', 0),
(12683, 'koKR', 'Wspaniale! Oto twoja zapłata, zgodnie z umową. I, eee, mała rada: przez kilka najbliższych dni zafunduj sobie długie, gorące kąpiele, jeśli to „uczucie pieczenia” nie ustąpi.', 0),
(12688, 'koKR', 'Dziękuję, że $guwolniłeś:uwolniłaś; Helice i $gdopilnowałeś:dopilnowałaś;, by bezpiecznie wróciła. Wszyscy zaczęliśmy się martwić, kiedy nie wracała z wyprawy po kryształy.', 0),
(12689, 'koKR', 'Cześć! Bardzo się cieszyć, że cię znowu widzieć!$b$bJa wiedzieć, że my przyjaciele. Ja wiedzieć! Ty $gdobry przyjaciel:dobra przyjaciółka;. Nie tylko dla nas, ale dla wszystkich Wyroczni.$b$bJa widzieć, jak ty dobrze walnąć tego pieskoczłowieka! Nieumarły stwór mówić, że on wcześniej twój przyjaciel? Ja tego nie wiedzieć. Ale ty już skończyć z pieskoludźmi, tak? Teraz już tylko $gprzyjaciel:przyjaciółka; Wyroczni?$b$bJa wiedzieć, że ty dobrze wybrać! Dziękować, że ty nas uratować! Dziękować, dziękować!', 0),
(12691, 'koKR', 'Ogromny kamienny klucz obraca się z głuchym zgrzytem, a wieko szkatuły unosi się, odsłaniając ukryty w środku skarb.', 0),
(12692, 'koKR', 'Dobrze cię znowu widzieć. Ja wiedzieć, że ty nie $gzdrajca:zdrajczyni;, ja się cieszyć, że Zepik udowodnić, że ja mieć rację.$b$bJa słyszeć, że ty teraz $gŁowca Liszy:Łowczyni Liszy; – to całkiem nieźle! Harkek być z ciebie dumny.', 0),
(12695, 'koKR', 'Dobrze cię znowu widzieć! My się martwić, jak ty nie wrócić od razu.$b$bJaloot wrócić przed tobą – Jaloot mieć dużo energii, on całkiem szybki. On mi opowiedzieć, jak ty go uratować przed liszem. Moodle mi opowiedzieć, jak ty uratować też Mchostąpów. Ty naprawdę $gmiły:miła;.$b$bJa mieć nadzieję, że ty zostać z nami na trochę. Zawsze coś trzeba zrobić.', 0),
(12696, 'koKR', 'Profesor przysłała cię do mnie? No dobrze.', 0),
(12699, 'koKR', 'Świetnie!', 0),
(12702, 'koKR', 'Ty w tym $gdobry:dobra;.$b$bMoże kiedyś my po prostu wrzucić Goregeka do rzeki, żebyś ty już nie musieć tego robić.', 0),
(12703, 'koKR', 'Rytuał pójść ci tak łatwo!$b$bTy wrócić kiedyś później po więcej zabijania, dobrze?', 0),
(12704, 'koKR', 'Tyle dobrych błyskotek! Ty w tym $gdobry:dobra;.$b$bWróć potem po więcej, tak?', 0),
(12705, 'koKR', 'Soo-holu silny, co? Ja bardzo się cieszyć, że on zgodzić się dzielić z tobą ciało do walki.$b$bOn bardziej ufać tym, których już spotkać, więc może wróć kiedyś znowu pomóc, tak?', 0),
(12726, 'koKR', 'Dziękuję ci, $N. Dzięki tobie wielka nawałnica spojrzy na nas łaskawie.', 0),
(12732, 'koKR', 'Rejek ci dziękować. Rejek wypić, stać się silny, zawsze pamiętać dar, co dać $gpotężny:potężna; $N.', 0),
(12734, 'koKR', 'Rejek widzieć na ostrzu plamy krwi swoich wrogów. Teraz Rejek mieć potężną broń dla potężnego wojownika, którym on zostać!', 0),
(12735, 'koKR', 'Wody... oczyszczone. Tak. Wszystko dobrze.$b$bTy rozumieć naszą drogę, $N.', 0),
(12736, 'koKR', 'Widzisz? Już widać, że ty $gmądrzejszy:mądrzejsza;. A jak nie $gmądrzejszy:mądrzejsza;... to... $gszczęśliwszy:szczęśliwsza;!', 0),
(12737, 'koKR', 'Ty szybko się uczyć, $N. Ty dobrze nauczyć się tej pieśni. Może następnym razem ja nauczyć cię innej.', 0),
(12741, 'koKR', 'Teraz Rejek pokazać tchórzliwym wielkojęzorom, jak naprawdę używać żywiołów!', 0),
(12758, 'koKR', 'Rejek widzieć, że tobie się udać! Teraz Rejek przymierzyć nowy hełm bojowy.', 0),
(12759, 'koKR', 'Ty z tymi pułapkami prawie tak $gdobry:dobra; jak Zepik!', 0),
(12760, 'koKR', 'Ty $gzaciekły wojownik:zaciekła wojowniczka;... wróć niedługo na więcej walki. Nigdy dość dobrej walki!', 0),
(12761, 'koKR', 'Dziękować, $gsuchoskóry:suchoskóra;.$b$bJa trzymać te kryształy tutaj, żeby nas chronić. Może ty niedługo wrócić i pomóc nam więcej.', 0),
(12762, 'koKR', 'Tyle energii w tobie... ty $gpełen:pełna; mocy Wielkich!$b$bJa nie kłamać, ja trochę zazdrosny.', 0),
(12803, 'koKR', 'Nie pochodzisz z tej krainy. Ale nie należysz też do Plagi.$b$bCo mam o tobie myśleć?', 0),
(12804, 'koKR', 'To mi dopiero posiłek! Jeśli z katastrofy statku wyniknęło coś dobrego, to chyba to, że przez następny miesiąc nie będziemy jeść samej solonej wołowiny! Jeszcze raz dziękuję, $N.', 0),
(12805, 'koKR', 'Dziękuję ci, $N. Szkoda, że filar runął, ale musimy ocalić, co się da.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(12520, 'koKR', '$GPoradziłeś:Poradziłaś; sobie z nosorożcami, czy rzucasz ręcznik na ring?', 0),
(12522, 'koKR', 'No i jak, $gzdobyłeś:zdobyłaś; silnik? Czuję, że arcymag, który sfinansował ekspedycję, zaczyna się niecierpliwić.', 0),
(12523, 'koKR', '$GZdobyłeś:Zdobyłaś; te części?', 0),
(12525, 'koKR', '$GRozprawiłeś:Rozprawiłaś; się z Cwaniuśmiechem i jego ochroniarzem?', 0),
(12529, 'koKR', 'Ty wciąż żyć! Twardopięści jeszcze ciebie nie zjeść?$B$BMoże zjeść później.', 0),
(12530, 'koKR', 'Czego ty chcieć, $gniewolniku:niewolnico;?', 0),
(12531, 'koKR', 'Ja ciebie nie wołać, $r. Czego ty chcieć?', 0),
(12532, 'koKR', 'Ty złapać kury?', 0),
(12533, 'koKR', 'Ty nauczyć się łowów?', 0),
(12534, 'koKR', 'Ty śmierdzieć osim czymś.', 0),
(12535, 'koKR', 'Prawie gotowe na długą podróż. Gekgek przed chwilą wrócić z krokoliszkiem.', 0),
(12536, 'koKR', 'Oni mówić Zepikowi, że ty $gdobry łowca:dobra łowczyni;, jak na kogoś spoza Szalonego Serca.', 0),
(12537, 'koKR', 'Zepik myśleć, że z partnerem pójść dużo lepiej. Ty $gsilny:silna; jak na kogoś spoza Szalonego Serca.', 0),
(12538, 'koKR', 'My najlepsi łowcy w kotlinie!', 0),
(12543, 'koKR', 'My musieć wiedzieć – czy ty przynieść kły?', 0),
(12544, 'koKR', 'No i jak, $gzasięgnąłeś:zasięgnęłaś; rady miejscowej wyroczni?', 0),
(12546, 'koKR', 'Ci, którzy zagrażają życiu... czy się z nimi $grozprawiłeś:rozprawiłaś;?', 0),
(12549, 'koKR', '$GSprawdziłeś:Sprawdziłaś; swoje umiejętności w starciu ze straszliwymi szablobestiami?', 0),
(12550, 'koKR', 'Jak idzie tropienie?', 0),
(12551, 'koKR', '$GUpolowałeś:Upolowałaś; je?', 0),
(12556, 'koKR', '$GZabiłeś:Zabiłaś; bestię?', 0),
(12558, 'koKR', '$GZmierzyłeś:Zmierzyłaś; się już z Shango?', 0),
(12559, 'koKR', '$GWróciłeś:Wróciłaś;, maleńka istoto. Zaczynałam się już o ciebie martwić.', 0),
(12560, 'koKR', '$GPrzyniosłeś:Przyniosłaś; wszystkie paprocie, których potrzebujemy?', 0),
(12561, 'koKR', 'Nie marnuj mojego czasu, $gśmiertelniku:śmiertelniczko;. Dzieł tytanów trzeba bronić!', 0),
(12569, 'koKR', 'Nasz plan zadziałał?', 0),
(12570, 'koKR', 'Kto ty? Ty śmierdzieć pieskoludźmi.', 0),
(12571, 'koKR', '<Arcywyrocznia Soo-say zdaje się patrzeć prosto przez ciebie.>', 0),
(12572, 'koKR', 'Witaj, $gsuchoskóry:suchoskóra;. Ty dobrze się dogadywać z Lafoo?', 0),
(12573, 'koKR', 'Pieskoludzie teraz grzeczni?', 0),
(12575, 'koKR', 'Głupie pieskozłodzieje.', 0),
(12576, 'koKR', 'Oni zawsze chcieć walki! My nie chcieć walki, ale my musieć chronić święte rzeczy.', 0),
(12578, 'koKR', 'Soo-say czasem się gubi, ale głupi nie jest. Myślę jednak, że jest o wiele za bardzo pobłażliwy... pieskoludzie nie przestaną i nie dadzą nam spokoju. Jedyny sposób, żeby ich powstrzymać, to ich zabić... nie ma żadnego „pokoju”.$B$B<Moodle wypina pierś i wskazuje na siebie.>$B$BA w tym jestem dobry.', 0),
(12579, 'koKR', 'Mchostąpowie byli dobrym ludem... nie zasłużyli na to.', 0),
(12580, 'koKR', 'Szkoda, że dużo wcześniej nie wiedziałem, jak ważne są filary i kamienie... może zdołałbym temu zapobiec.', 0),
(12581, 'koKR', '<Filakteria złowieszczo spoczywa na ziemi obok martwego ciała Artruisa.>', 0),
(12589, 'koKR', '$GZadowolony:Zadowolona; z wyników?', 0),
(12592, 'koKR', 'Policzymy?', 0),
(12603, 'koKR', '$GSprawdziłeś:Sprawdziłaś; swoje umiejętności?', 0),
(12605, 'koKR', '$GZdobyłeś:Zdobyłaś; przynętę, której potrzebujemy, by zwrócić uwagę matki miotu?', 0),
(12607, 'koKR', 'Wszystko załatwione?', 0),
(12614, 'koKR', 'No, żyjesz. Jak poszło?', 0),
(12617, 'koKR', '$GZniszczyłeś:Zniszczyłaś; intruzów, $N?', 0),
(12620, 'koKR', '$GZająłeś:Zajęłaś; się kultystami, $N?', 0),
(12621, 'koKR', 'Mamy mało czasu. Plaga szykuje się do ostatecznego natarcia.', 0),
(12624, 'koKR', 'Pierścionek, $N! Proszę... powiedz, że go $gznalazłeś:znalazłaś;!', 0),
(12634, 'koKR', 'Udało ci się wydrzeć trochę owoców tym cholernie wysokim i skąpym drzewom?', 0),
(12644, 'koKR', 'No i jak wyszło?', 0),
(12645, 'koKR', 'Nie każ mi czekać, $N. Jakie wyniki?', 0),
(12654, 'koKR', '$GZnalazłeś:Znalazłaś; Pitcha?', 0),
(12658, 'koKR', 'Masz te jaja?', 0),
(12681, 'koKR', 'Udało ci się znaleźć jakieś wykrzywione szpony?', 0),
(12683, 'koKR', '$GZdobyłeś:Zdobyłaś; te próbki?', 0),
(12691, 'koKR', 'Kamienna szkatuła ani drgnie.', 0),
(12699, 'koKR', '$GZnalazłeś:Znalazłaś; już coś, $N?', 0),
(12702, 'koKR', 'Kury zwykle nie uciekać daleko... jak osy ich nie zjeść, to może następnym razem my je po prostu zostawić na polu.', 0),
(12703, 'koKR', 'Tyle wielkojęzorów do zabicia! Taka zabawa, co?', 0),
(12704, 'koKR', 'Nigdy dość błyskotek... Wielki Kamień Deszczu dobry dla nas, my musieć być dobrzy dla Wielkiego Kamienia Deszczu.', 0),
(12705, 'koKR', 'Dziękować za pomoc, $gsuchoskóry:suchoskóra;. Ty bardzo $gdobry:dobra; dla nas.', 0),
(12732, 'koKR', 'Ty przynieść Rejekowi dar?', 0),
(12734, 'koKR', 'Ty splamić krwią ostrze Rejeka?', 0),
(12735, 'koKR', 'Ty już zagrać pieśń oczyszczenia, $N?', 0),
(12736, 'koKR', 'Ty już czuć się $gmądry:mądra;, $N?', 0),
(12741, 'koKR', 'Ty przynieść Rejekowi prawdziwą moc żywiołów?', 0),
(12758, 'koKR', 'Ty przynieść Rejekowi nowy hełm?', 0),
(12759, 'koKR', 'Trochę bałagan! Ale i tak super zabawa.', 0),
(12760, 'koKR', 'Vekgar nauczyć cię super sekretu, co? Tylko najsilniejsi z Szalonego Serca poznać sekret.', 0),
(12761, 'koKR', 'Bardzo potężne. Pieskoludzie nie wiedzieć o mocy Wielkich. Głupie pieskoludzie.', 0),
(12762, 'koKR', 'Dobrze, że ty tu być i nam pomóc. Długa walka.', 0),
(12804, 'koKR', '$GZdobyłeś:Zdobyłaś; te steki?', 0),
(12805, 'koKR', '$GOdzyskałeś:Odzyskałaś; energię żywiołaków, $N?', 0);
