INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(27417, 'koKR', 'Nazywam ją Duchem Gnomoregan. Piękna maszyna, co? Bez twojej pomocy nigdy by jej nie odbudowano.', '', 0),
(27537, 'koKR', 'Naprzód, robactwo! Ta ziemia należy teraz do Króla Lisza!', '', 0),
(27538, 'koKR', 'Nic nie powstrzyma Plagi! Nic!', '', 0),
(27539, 'koKR', 'Miażdżcie wszystko, co stanie wam na drodze! Za Króla Lisza!', '', 0),
(27604, 'koKR', '<Ranna wyrocznia Deszczomówców jęczy z bólu.>', '', 0),
(27605, 'koKR', 'Nie! Ty ukraść zdobycz! Teraz ty $gdłużny:dłużna; Gekgek!', '', 0),
(27607, 'koKR', '%s wrzeszczy z wściekłości i rzuca się na pomoc swoim młodym.', '', 0),
(27610, 'koKR', 'Tutaj, na południowy wschód. Widzę, że ciebie też dopadli...', '', 0),
(27620, 'koKR', 'Wyślę cię moją fruwającą maszyną. Wypatruj wszelkich śladów tego, co mogło się przydarzyć Hemetowi!', '', 0),
(27697, 'koKR', 'A więc wyrocznia postanowiła ci pomóc, $gprzybyszu:przybyszko;. Dobrze więc, podzielę się z tobą tym, co wiem.', '', 0),
(27698, 'koKR', 'Twój towarzysz szuka Farunna, patriarchy odłamkorogich, który trzyma się z dala od swoich braci.', '', 0),
(27699, 'koKR', 'Farunn przemierza ziemie na północ od miejsca, które twój lud nazywa Wodospadami Gorzkiej Fali. Znajdziesz go samego, ale przekonasz się, że nie potrzebuje obrońców.', '', 0),
(27701, 'koKR', 'Wróć do swojego towarzysza. Powiedz mu, by ruszył i zdobył swoje trofeum – Farunna.', '', 0),
(27702, 'koKR', 'A gdy już to zrobi, niech zostawi tę ziemię w spokoju. Nie jest jej częścią.', '', 0),
(27723, 'koKR', '<Uwięziony krokoliszek nisko warczy, gdy podchodzisz.>', '', 0),
(27724, 'koKR', 'Wyglądasz dość niegroźnie... zróbmy to.', 'Wyglądasz dość niegroźnie... zróbmy to.', 0),
(27732, 'koKR', '<Schyl się i pomóż rannej wyroczni Deszczomówców stanąć na nogi.>', '<Schyl się i pomóż rannej wyroczni Deszczomówców stanąć na nogi.>', 0),
(27752, 'koKR', 'Dzięki!', 'Dzięki!', 0),
(27753, 'koKR', 'Dom niedaleko. Chodź!', 'Dom niedaleko. Chodź!', 0),
(27754, 'koKR', 'Aaa! To iść prosto na nas!', '', 0),
(27755, 'koKR', 'Tylko nie wąsy! Teraz jestem niesymetryczny!', '', 0),
(27756, 'koKR', 'Moje ucho! $gDrasnąłeś:Drasnęłaś; mi ucho!', '', 0),
(27757, 'koKR', 'Au! Dość tego, rzucam robotę żywej tarczy!', '', 0),
(27761, 'koKR', 'Spokojnie, chłopcze, to tylko śrut na ptaki!', '', 0),
(27762, 'koKR', 'Phi, nawet ci z tym lepiej.', '', 0),
(27764, 'koKR', 'Przestań jęczeć. Szczęście cię nie opuściło.', '', 0),
(27765, 'koKR', 'Ucierpiała tylko twoja duma, chłopcze. Głowa do góry!', '', 0),
(27778, 'koKR', 'Dobry strzał!', '', 0),
(27785, 'koKR', 'Ranna wyrocznia Deszczomówców niezdarnie podnosi się na nogi.', 'Ranna wyrocznia Deszczomówców niezdarnie podnosi się na nogi.', 0),
(27798, 'koKR', '$gGłupi przyjaciel:Głupia przyjaciółka; wielkojęzorów! Ty już nie przyjaciel Szalonego Serca. Szalone Serce cię porządnie dopaść.', '', 0),
(27799, 'koKR', 'O nie! Jacyś pieskoludzie iść za nami!', 'O nie! Jacyś pieskoludzie iść za nami!', 0),
(27826, 'koKR', 'Ty powiedzieć, kiedy czas do domu.', '', 0),
(27831, 'koKR', 'Słyszysz w pobliżu niskie, gardłowe warczenie.', '', 0),
(27833, 'koKR', 'Vekjik nie chcieć, żeby mu przeszkadzać.', '', 0),
(27834, 'koKR', 'Szamanie Vekjiku, $grozmawiałem:rozmawiałam; z wielkojęzorami i oni pragną pokoju. $gPrzyniosłem:Przyniosłam; ten dar w ich imieniu.', 'Szamanie Vekjiku, $grozmawiałem:rozmawiałam; z wielkojęzorami i oni pragną pokoju. $gPrzyniosłem:Przyniosłam; ten dar w ich imieniu.', 0),
(27835, 'koKR', '$gObrzydliwy przyjaciel:Obrzydliwa przyjaciółka; wielkojęzorów, ty tu nie należeć. Idź precz z ziemi Szalonego Serca, albo ja wezwać magiczne rzeczy, żeby cię zabić!', '', 0),
(27836, 'koKR', 'Szalone Serce nigdy nie być przyjaciółmi wielkojęzorów. Ty głupie, że tu wracać, zdradzieckie coś!', '', 0),
(27837, 'koKR', 'Szalone Serce cię zabić, jak ty wrócić. Ty tu już nie $gmile widziany:mile widziana;!', '', 0),
(27838, 'koKR', 'Nie, nie... Nie $gmiałem:miałam; zamiaru zdradzić waszego ludu. Tylko się $gbroniłem:broniłam;. To było jedno wielkie nieporozumienie.', 'Nie, nie... Nie $gmiałem:miałam; zamiaru zdradzić waszego ludu. Tylko się $gbroniłem:broniłam;. To było jedno wielkie nieporozumienie.', 0),
(27893, 'koKR', 'Mój skarb! Ty nie kraść od Tarteka, głupie wielkojęzorowe zdradzieckie coś.', '', 0),
(27895, 'koKR', 'Tartek i paskudny smok zaraz cię zabić! Ty $gtaki głupi:taka głupia;.', '', 0),
(27900, 'koKR', '$GWidziałeś:Widziałaś; kiedyś takie smoki jak tutejsze? Idealne do polowania.', '', 0),
(27965, 'koKR', 'Starszy może gadać co innego, ale ty zawsze być niewolnicze coś dla Goregeka.', '', 0),
(27969, 'koKR', 'Pitch i tak być słabeusz... a jak ty myśleć, czemu Goregek się nim nie przejmować?', '', 0),
(27981, 'koKR', 'Szalone Serce karmić Kartaka wielkojęzorami, żeby Kartak nie zjeść nas. Dlatego my mądrzejsi od ciebie, niewolnicze coś.', '', 0),
(27983, 'koKR', 'Szalone Serce najsilniejsze!', '', 0),
(27984, 'koKR', 'Dom! Lepiej, żeby ty przynieść mięso dla Goregeka, $gniewolniku:niewolnico;.', '', 0),
(27985, 'koKR', 'Goregek iść po picie. Ty siedzieć w kącie, aż Goregek gotowy.', '', 0),
(27986, 'koKR', 'Goregek głodny. Idź na rożen nad ogniem, niewolnicze coś. Powiedz Goregekowi, jak ty się dobrze upiec.', '', 0),
(27987, 'koKR', 'Ty czekać, aż Goregek gotowy.', '', 0),
(27988, 'koKR', 'Goregek iść spać. Idź przynieść żarcie, niewolnicze coś.', '', 0),
(27990, 'koKR', 'Kiedyś tu być setki razy więcej twardopięściów, zanim przyjść Goregek.', '', 0),
(27991, 'koKR', 'Twardopięście dalej chodzić na rękach... dla Goregeka to trochę głupie.', '', 0),
(27992, 'koKR', 'Ty tylko patrzeć, niewolnicze coś, Goregek zająć się tymi twardopięściami!', '', 0),
(27993, 'koKR', 'Lepiej nie wchodzić Goregekowi w drogę!', '', 0),
(27994, 'koKR', 'Ty tylko dać się pobić! Ha! Ty takie głupie, niewolnicze coś.', '', 0),
(27995, 'koKR', 'Uważaj, niewolnicze coś, wielkie złe miękkopięście mogą cię zjeść! Ha!', '', 0),
(28009, 'koKR', 'Ha! Zdobycz Goregeka!', '', 0),
(28011, 'koKR', 'Goregek najlepszy łowca... w historii.', '', 0),
(28012, 'koKR', 'Ja go dźgnąć prosto w twarz! Goregek taki dobry.', '', 0),
(28015, 'koKR', 'Po co Goregek w ogóle cię brać. Ty bezużyteczne.', '', 0),
(28016, 'koKR', 'Następnym razem może Goregek pozwolić tobie spróbować.', '', 0),
(28026, 'koKR', 'Ale walkę przegapiłeś, Dorianie! Będą o niej śpiewać przez wieki!', '', 0),
(28027, 'koKR', 'I tak oto pędziliśmy do bitwy co sił w nogach, na grzbiecie Tupcia...', '', 0),
(28037, 'koKR', 'Cóż, nie wiem. Siedziałem tu, pilnowałem ogniska i rozprawiałem z Zootfizzle\'em o wadach zębatek. Na swój sposób to też dość epickie.', '', 0),
(28056, 'koKR', 'Z drogi, głupie niewolnicze coś! Zdobycz Goregeka!', '', 0),
(28057, 'koKR', 'Ha! Goregek najlepszy łowca w historii! Goregek dopaść największego twardopięścia!', '', 0),
(28058, 'koKR', 'Tak to się robić, niewolnicze coś. Może ty kiedyś się nauczyć.', '', 0),
(28062, 'koKR', 'Ty czekać, niewolnicze coś. Goregek jeść.', '', 0),
(28065, 'koKR', 'Goregek porządnie złapać kurczaka!', '', 0),
(28068, 'koKR', 'Kwik! Kwik! Jak dobrze!', '', 0),
(28069, 'koKR', 'Uciekaj, miękkopięściu! Goregek cię dopaść!', '', 0),
(28071, 'koKR', 'Uciekaj, głupi miękkopięściu! My cię jeszcze poszturchać!', '', 0),
(28201, 'koKR', 'Dajik próbować pokazać mi, jak polować, ale ja lepiej sobie radzić po swojemu.', '', 0),
(28202, 'koKR', 'Przynieś dobre mięso, a obóz traktować cię cały dzień jak wielkiego szamana. Dobry interes.', '', 0),
(28203, 'koKR', 'Ty powinien znowu wypuścić kury i powiedzieć, że to Goregek. To się nigdy nie nudzić.', '', 0),
(28204, 'koKR', 'Ja się nie spieszyć. My móc tu chwilę odpocząć, jak ty chcieć.', '', 0),
(28205, 'koKR', 'Ja nie zawsze tu mieszkać... Niedawno ja sam podróżować po dużym kawałku świata. Ja lubić wszystkie opowieści o bestiach, smokach, bogach i takich.', '', 0),
(28206, 'koKR', 'Starszy Harkek to całkiem dobry wolvar z Szalonego Serca. On dużo mi pomagać, jak ja być mniejszy i nie lubić Dajika.', '', 0),
(28223, 'koKR', 'Haha! Ty widzieć? Błyskawica trafić go prosto w głowę!', '', 0),
(28224, 'koKR', 'BUM! To takie dobre! Jeszcze! Jeszcze!', '', 0),
(28227, 'koKR', 'To jezioro tu obok naprawdę pełne morskich stworów. Nie wiem, jak one się tu dostać... może w powodzi?', '', 0),
(28228, 'koKR', 'Ja chyba dlatego tak lubić polować na wielkojęzory... one nie takie głupie jak inna zwierzyna. One naprawdę walczyć.', '', 0),
(28229, 'koKR', 'Wielkojęzory z Szeptu Mgły czasem sprytne z tą swoją kapliczką... zakryć mgłą cały teren i wtedy trudno kogoś znaleźć.', '', 0),
(28233, 'koKR', 'Goregek nigdy nie „wpaść przypadkiem” do kurnika... Goregek zawsze musieć nakarmić swój głupi brzuch. Zawsze jednej kury brakować, jak my złapać wszystkie.', '', 0),
(28235, 'koKR', 'Ty całkiem $gdobry:dobra;! $gUrodzony łowca:Urodzona łowczyni;, jak ja.', '', 0),
(28236, 'koKR', 'Goregek myśleć, że on szef wszystkich, ale on za dużo jeść i za mało polować.', '', 0),
(28237, 'koKR', 'Dajik zapominać, co robić, gdzie być... czasem nawet zapominać własne imię. Przez to on czasem nie taki dobry nauczyciel.', '', 0),
(28238, 'koKR', 'Ty kiedyś walczyć z wielkim smokiem albo bogiem, albo czymś? Zepik lubić słuchać opowieści.', '', 0),
(28239, 'koKR', 'Dobre! On nawet tego nie zobaczyć.', '', 0),
(28240, 'koKR', 'Ha! Zostaw coś dla Zepika.', '', 0),
(28241, 'koKR', 'Koniec zabawy?', '', 0),
(28242, 'koKR', 'Ogień! Śmierć! Zniszczenie! Czarny płomień szaleje w moim sercu! Muszę... go uwolnić! Haha!', '', 0),
(28261, 'koKR', 'Ooo! Błyskotki!', '', 0),
(28265, 'koKR', 'Skarb dla Lafoo! Skarb dla kapliczki!', '', 0),
(28266, 'koKR', 'Kop, kop, kop...', '', 0),
(28267, 'koKR', 'Może więcej błyszczących robaków! My lubić robaki!', '', 0),
(28277, 'koKR', 'Tym razem nie wracać!', '', 0),
(28279, 'koKR', 'Sss... sss... martwe. Wszystkie martwe.', '', 0),
(28286, 'koKR', 'Ty mieć śmieszne gały.', '', 0),
(28289, 'koKR', 'Lafoo nigdy nie spotkać Wielkich. Nie, tylko ich kapliczki.', '', 0),
(28290, 'koKR', 'Duże wygodne drzewo. Dobry dom.', '', 0),
(28291, 'koKR', 'Chrupiące robaki takie pyszne. Chcesz?', '', 0),
(28293, 'koKR', 'Kiedyś może ty być Soo-$gsuchoskóry:suchoskóra;. Podobać się?', '', 0),
(28303, 'koKR', 'To dziwne. Ktoś zabrać nasze robaki. Ty może mieć?', '', 0),
(28306, 'koKR', 'Ty mieć placek? Ktoś dać nam placek rok temu. Bardzo pyszny.', '', 0),
(28340, 'koKR', 'Dom dobry, ale nie zostawać długo! Więcej przygód!', '', 0),
(28363, 'koKR', 'Hurra... więcej ziemi.', '', 0),
(28365, 'koKR', 'Hej... może znajdziemy jeszcze trochę bezużytecznych robaków.', '', 0),
(28366, 'koKR', 'A co tu w ogóle robią błyszczące króliki?', '', 0),
(28368, 'koKR', 'Oto jestem, wykopuję z ziemi jakąś bezużyteczną błyskotkę na rozkaz kogoś, kogo dopiero co poznałem... czy to wydaje ci się w porządku?', '', 0),
(28377, 'koKR', 'Nie mogę uwierzyć... oni wszyscy... nie żyją.', '', 0),
(28382, 'koKR', 'Soo-say nawet się nie zainteresował, kiedy Mchostąpowie wspominali o dziwnej pogodzie, a teraz wszyscy nie żyją... czy to wydaje ci się w porządku?', '', 0),
(28384, 'koKR', 'Kolejny pada pod naszym naporem.', '', 0),
(28391, 'koKR', 'No, chodźmy już.', '', 0),
(28392, 'koKR', 'Skończyłem tutaj.', '', 0),
(28393, 'koKR', 'Jest jakiś powód, dla którego wciąż tu stoimy? Chętnie go usłyszę.', '', 0),
(28396, 'koKR', 'Jestem najinteligentniejszym, najsilniejszym i najbardziej kulturalnym gorlokiem w okolicy, a mimo to o wszystkim decyduje Soo-say... czy to wydaje ci się w porządku?', '', 0),
(28400, 'koKR', 'Marne to pocieszenie, ale przynajmniej żadnego z nich nie przywrócili jako nieumarłego.', '', 0),
(28475, 'koKR', 'Ha! Teraz najlepsza część!', '', 0),
(28477, 'koKR', 'Zaufaj mi – ty to pokochać!', '', 0),
(28478, 'koKR', 'Masz za swoje, wielkojęzory!', '', 0),
(28492, 'koKR', '$gGłupi:Głupia;! Nie strzelać do tego! Gekgek chcieć trofeum w jednym kawałku!', '', 0),
(28493, 'koKR', 'Nie dać mu uciec! Tym razem my go mieć.', '', 0),
(28495, 'koKR', 'Uważaj! Nie dać się podrapać jak ostatnio.', '', 0),
(28513, 'koKR', 'Wszystko przygotowane i gotowe do startu.', '', 0),
(28514, 'koKR', 'Rozpoczynam destylację za 5 sekund.', '', 0),
(28515, 'koKR', 'Dodaj jeszcze jedną pomarańczę! Szybko!', '', 0),
(28516, 'koKR', 'Dodaj banany!', '', 0),
(28517, 'koKR', 'Wrzuć papaję do aparatury!', '', 0),
(28518, 'koKR', 'Aparatura potrzebuje ciepła! Rozpal koksownik!', '', 0),
(28519, 'koKR', 'Za wysokie ciśnienie! Otwórz zawór ciśnieniowy!', '', 0),
(28521, 'koKR', 'Udało się! Chodź po beczułkę.', '', 0),
(28523, 'koKR', 'Nic z tego! Wyłączam...', '', 0),
(28524, 'koKR', 'Dobra robota! Bądź $ggotów:gotowa; na wszystko!', '', 0),
(28532, 'koKR', '$gJestem gotów:Jestem gotowa; zacząć destylację, eee... Podchmielony.', '$gJestem gotów:Jestem gotowa; zacząć destylację, eee... Podchmielony.', 0),
(28533, 'koKR', 'Ładnie załatwione! Miej się na baczności!', '', 0),
(28534, 'koKR', 'Dobra robota! A teraz miej oczy szeroko otwarte.', '', 0),
(28535, 'koKR', 'Wystarczy. Nigdy nie wiadomo, czego będzie trzeba za chwilę...', '', 0),
(28536, 'koKR', 'Konstrukcja w górze zaczyna buczeć energią.', '', 0),
(28546, 'koKR', '', 'Jasne!', 0),
(28548, 'koKR', '', 'Smakuje, jakbym piła... odtłuszczacz do silników!', 0),
(28549, 'koKR', 'No, spróbuję.', '', 0),
(28550, 'koKR', 'Dokładnie tego mi było trzeba!', '', 0),
(28551, 'koKR', 'Ma mój głos! Od tego włosy na piersi wyrosną ci jak od niczego innego.', '', 0),
(28554, 'koKR', 'Na trunek od Grimbooze\'a zawsze mam ochotę.', '', 0),
(28556, 'koKR', 'Cóż, na razie smakuje jak coś, co piłaby moja żona...', '', 0),
(28557, 'koKR', 'No, to jest ten kopniak, jakiego oczekuję po trunkach Grimbooze\'a! Podoba mi się!', '', 0),
(28589, 'koKR', 'Ten posterunek jest strefą wolną od zębatek. Osoby używające zębatek do budowy urządzeń mechanicznych narażają się na bezlitosne drwiny.', '', 0),
(28630, 'koKR', 'Proszę, weź... moje błyskotki. Koniec ze mną...', '', 0),
(28631, 'koKR', 'My uratowani. Ty $gmiły, suchoskóry:miła, suchoskóra;.', '', 0),
(28632, 'koKR', 'Mchostąp wygląda na ciężko rannego.', '', 0),
(28633, 'koKR', '<Sprawdź puls...>', '<Sprawdź puls...>', 0),
(28638, 'koKR', 'Ofiara Mchostąpów jęczy z bólu.', '', 0),
(28641, 'koKR', 'Moja biedna fruwająca maszyna. Nie przetrwała katastrofy, a bez części zamiennych nigdy jej znowu nie uruchomię!', '', 0),
(28646, 'koKR', 'Ach, $gbohater:bohaterka;. Twoi mali przyjaciele mówili, że przyjdziesz. To z pewnością oszczędza mi trudu samodzielnego polowania na ciebie.', '', 0),
(28647, 'koKR', 'Przetrwałem sto lat wojny i cierpienia. Czy naprawdę uważasz, że to rozsądne, stawiać śmiertelne ciało przeciw istocie, która nie może umrzeć? Śmiem twierdzić, że masz więcej do stracenia.', '', 0),
(28648, 'koKR', 'Nawet rozbite na niezliczone kawałki, otaczające mnie kryształy mnie osłabiają... może nie powinienem był tak nie doceniać tytanów...', '', 0),
(28649, 'koKR', 'Ci dwaj dzielni, nieświadomi głupcy nienawidzą się nawzajem, a jednak obaj mówili o tobie jak o $gbohaterze:bohaterce;. Może po prostu brak ci woli, by wybrać stronę... pozwól, że dam ci taką sposobność.', '', 0),
(28650, 'koKR', 'Arthas również zebrał kiedyś siłę... dokładnie tego samego rodzaju... być może podążysz jego ścieżką.', '', 0),
(28834, 'koKR', 'Mam nadzieję, że arcymag doceni, przez co przeszedłem, żeby dotrzymać Hemetowej części umowy.', '', 0),
(28856, 'koKR', '', 'Wynośmy się stąd do diabła.', 0),
(28857, 'koKR', '', 'Słuchajcie, zbiry ze spółki Gitgeszeft! Zasada nr 1: nigdy nie trzymajcie więźnia obok materiałów wybuchowych.', 0),
(28859, 'koKR', '', 'Bo inaczej czeka was TO.', 0),
(28860, 'koKR', '', 'Robi się tu trochę gorąco. Idziemy dalej?', 0),
(28862, 'koKR', '', 'O, patrzcie, kolejny wózek materiałów wybuchowych! Pomóżmy im się go pozbyć.', 0),
(28864, 'koKR', '', 'Naprawdę nie powinniście się bawić takimi rzeczami. Ktoś mógłby ucierpieć.', 0),
(28865, 'koKR', '', 'Udało się! Dziękuję, że $gwyciągnąłeś:wyciągnęłaś; mnie z tej piekielnej dziury. Powiedz Hemetowi, żeby się mnie spodziewał!', 0),
(28873, 'koKR', 'Ta walka należy do ciebie!', '', 0),
(28881, 'koKR', 'Miłej jazdy! Wezwij mnie, jak ty dojechać.', '', 0),
(28883, 'koKR', 'Szalone Serce wziąć tę ziemię dla siebie. Wielkojęzory odejść albo my je porządnie pozabijać.', '', 0),
(28885, 'koKR', 'Szalone Serce umieć być okrutne, ale my dobry lud. Ty zobaczyć, jak zostać dłużej – z mądrymi i silnymi my się przyjaźnić bez problemu.$B$BMy tylko nie lubić głupich.', '', 0),
(28886, 'koKR', 'To Wielki Kamień Deszczu. My go strzec i przynosić mu błyskotki, a on się nami opiekować.$B$BMoże ty mieć więcej błyskotek dla kamienia?', '', 0),
(28887, 'koKR', 'Czego mi brakować we wzroście, to ja nadrabiać magią. Ja dobrze dbać o Wielki Kamień Mgły... przeważnie.$B$BGłupie pieskoludzie.', '', 0),
(28888, 'koKR', 'Pieskoludzie atakować nas od wielu dni. Ale Wielki Kamień Błyskawic dalej bezpieczny.$B$BSoo-holu przyjść nam pomóc, jak wiele razy wcześniej... pieskoludzie nie mieć szans.', '', 0),
(28889, 'koKR', 'Kartak przychodzić po mięso wielkojęzorów. Szalone Serce pilnować, żeby było go dużo.', '', 0),
(28892, 'koKR', 'To twój szczęśliwy dzień, Zootfizzle. $n $gprzyniósł:przyniosła; ci więcej piskląt.', '', 0),
(28893, 'koKR', 'Nie jestem tu po to, żeby niańczyć twoje pisklęta, Dorianie. Sam też prowadzę badania.', '', 0),
(28894, 'koKR', 'Cóż, zawsze możesz wrócić do obozu i pomagać Weslexowi przy tych wszystkich jego zębatkach...', '', 0),
(28895, 'koKR', 'Nie, tylko nie zębatki! Wszystko, byle nie zębatki!', '', 0),
(28900, 'koKR', 'My dawać błyskotki kapliczce... my nie chciwi... czemu to się stać?', '', 0),
(28901, 'koKR', 'Użyj moich błyskotek... zrób znowu dobrą pogodę... przegoń nieumarłe rzeczy.', '', 0),
(28903, 'koKR', 'My nic... im nie zrobić... ja nie rozumieć.', '', 0),
(28904, 'koKR', 'Ja zrobić coś złego? Ja przepraszać...', '', 0),
(28905, 'koKR', 'Dziękować! Ty $gdobry:dobra;!', '', 0),
(28906, 'koKR', 'Może ty też naprawić pogodę?', '', 0),
(28909, 'koKR', 'Ty nas uratować! Hurra dla ciebie!', '', 0),
(28910, 'koKR', 'Witaj, $gsuchoskóry:suchoskóra;.', '', 0),
(28912, 'koKR', 'Wszystko dobrze?', '', 0),
(28913, 'koKR', 'Tak?', '', 0),
(28914, 'koKR', 'Fajnie mieć dobrego towarzysza polowań.', '', 0),
(28915, 'koKR', 'Coś nie tak?', '', 0),
(28923, 'koKR', 'Na co się gapisz?', '', 0),
(28924, 'koKR', 'Jest jakiś powód, dla którego wciąż tu stoimy?', '', 0),
(28925, 'koKR', 'Zakładam, że czegoś chcesz.', '', 0),
(28936, 'koKR', 'Teraz ty nas nie złapać odwróconych plecami! Teraz my ci zrobić krzywdę, złe nieumarłe. ZŁE!', '', 0),
(28937, 'koKR', 'Ty zaraz zginąć, wielkie złe nieumarłe coś! Tym razem ty nie złapać Zepika śpiącego!', '', 0),
(28952, 'koKR', 'Muszę znaleźć Goregeka. Masz jego kajdany?', 'Muszę znaleźć Goregeka. Masz jego kajdany?', 0),
(28953, 'koKR', 'Muszę znaleźć Dajika. Masz jego kredę?', 'Muszę znaleźć Dajika. Masz jego kredę?', 0),
(28954, 'koKR', 'Muszę znaleźć Zepika. Masz jego róg myśliwski?', 'Muszę znaleźć Zepika. Masz jego róg myśliwski?', 0),
(28961, 'koKR', 'Muszę znaleźć Lafoo. Masz jego torbę na robaki?', 'Muszę znaleźć Lafoo. Masz jego torbę na robaki?', 0),
(28962, 'koKR', 'Muszę znaleźć Jaloota. Masz jego ulubiony kryształ?', 'Muszę znaleźć Jaloota. Masz jego ulubiony kryształ?', 0),
(28963, 'koKR', 'Muszę znaleźć Moodle\'a. Masz jego piłeczkę antystresową?', 'Muszę znaleźć Moodle\'a. Masz jego piłeczkę antystresową?', 0),
(28970, 'koKR', 'Piękny dzień na latanie, prawda?', '', 0),
(28971, 'koKR', 'Poznaję asa, gdy go widzę. Jeszcze raz dzięki za uratowanie mi życia!', '', 0),
(29244, 'koKR', '', 'Nie na to się pisałam, ale cóż... przynajmniej jest tu ciepło.', 0),
(29247, 'koKR', 'Dalej ciepłe, tak jak Rejek lubić.', '', 0),
(29248, 'koKR', 'Rejek czuć się silny! Rejek zmiażdżyć gołymi rękami czaszki wielkojęzorów!', '', 0),
(29249, 'koKR', 'Rejek i $n nauczyć wrogów Szalonego Serca bać się nas!', '', 0),
